/**
 * Worker da Solua Imóveis — formulário de candidatura para corretores(as) parceiros(as).
 * Versão "arquivo único" para colar no editor de código do painel da Cloudflare
 * (Workers & Pages → formsvagas → Edit code).
 *
 * Depois de colar e clicar em "Deploy", configure em Settings → Variables and Secrets:
 *  1) D1 database binding → variable name "DB" → banco "solua-candidaturas"
 *  2) Secret de texto → variable name "ADMIN_TOKEN" → uma senha sua escolha
 *     (protege o painel de candidaturas em /admin)
 */

const INDEX_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n  <title>Trabalhe com a Solua Imóveis</title>\n  <meta name=\"description\" content=\"Cadastro de corretores(as) parceiros(as) — Solua Imóveis\" />\n  <meta name=\"theme-color\" content=\"#024ba5\" />\n  <link rel=\"preconnect\" href=\"https://api.fontshare.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"/styles.css\" />\n</head>\n<body>\n  <div id=\"app\">\n\n    <!-- ===================== TELA INICIAL ===================== -->\n    <section class=\"hero\" data-screen=\"landing\">\n      <div class=\"hero__media\">\n        <img class=\"hero__image\" id=\"landing-image\" src=\"/images/placeholder.svg\" alt=\"\" />\n        <div class=\"hero__overlay\" id=\"landing-overlay\"></div>\n        <img class=\"brand-logo hidden\" id=\"landing-logo\" alt=\"\" />\n      </div>\n      <div class=\"hero__content\">\n        <h1 class=\"hero__title\" id=\"landing-title\">Vagas para corretores (as)</h1>\n        <p class=\"hero__subtitle\" id=\"landing-subtitle\">\n          Leva menos de 5 minutos. Conte um pouco sobre sua experiência e a forma como você atua\n          no mercado imobiliário para darmos início à conversa.\n        </p>\n        <button class=\"btn btn-primary\" id=\"btn-start\" type=\"button\">Iniciar</button>\n      </div>\n    </section>\n\n    <!-- ===================== FORMULÁRIO (multi-etapas) ===================== -->\n    <form id=\"form\" class=\"hidden\" novalidate>\n\n      <!-- honeypot anti-spam -->\n      <div class=\"honeypot\" aria-hidden=\"true\">\n        <label>Não preencha este campo<input type=\"text\" name=\"website\" id=\"website\" tabindex=\"-1\" autocomplete=\"off\" /></label>\n      </div>\n\n      <!-- ETAPA 1 -->\n      <section class=\"step\" data-step=\"1\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">01</span>\n        <h2 class=\"step__title\">Seus dados</h2>\n        <p class=\"step__desc\">Para começarmos, precisamos te conhecer.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"nome\">Nome completo</label>\n          <input type=\"text\" id=\"nome\" name=\"nome\" autocomplete=\"name\" required />\n          <span class=\"field-error\">Informe seu nome completo.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"email\">E-mail</label>\n          <input type=\"email\" id=\"email\" name=\"email\" autocomplete=\"email\" required />\n          <span class=\"field-error\">Informe um e-mail válido.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"whatsapp\">WhatsApp (com DDD)</label>\n          <span class=\"field__hint\">É por aqui que faremos o primeiro contato.</span>\n          <input type=\"tel\" id=\"whatsapp\" name=\"whatsapp\" placeholder=\"(00) 00000-0000\" autocomplete=\"tel\" required />\n          <span class=\"field-error\">Informe um WhatsApp com DDD.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"cidade\">Cidade / Estado</label>\n          <input type=\"text\" id=\"cidade\" name=\"cidade\" placeholder=\"Ex.: Fortaleza / CE\" required />\n          <span class=\"field-error\">Informe cidade e estado.</span>\n        </div>\n      </section>\n\n      <!-- ETAPA 2 -->\n      <section class=\"step hidden\" data-step=\"2\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">02</span>\n        <h2 class=\"step__title\">Dados profissionais</h2>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"creci\">Número do CRECI (opcional)</label>\n          <input type=\"text\" id=\"creci\" name=\"creci\" />\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Tempo de experiência como corretor(a)</label>\n          <div class=\"options\" data-name=\"experiencia\" data-error=\"Selecione uma opção.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-a\" value=\"Menos de 1 ano\" />\n              <label for=\"exp-a\"><span class=\"option__letter\">A</span>Menos de 1 ano</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-b\" value=\"1 a 3 anos\" />\n              <label for=\"exp-b\"><span class=\"option__letter\">B</span>1 a 3 anos</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-c\" value=\"3 a 5 anos\" />\n              <label for=\"exp-c\"><span class=\"option__letter\">C</span>3 a 5 anos</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-d\" value=\"Mais de 5 anos\" />\n              <label for=\"exp-d\"><span class=\"option__letter\">D</span>Mais de 5 anos</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"experiencia\">Selecione uma opção.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Já atuou diretamente com captação de imóveis?</label>\n          <span class=\"field__hint\">Prospecção de proprietários, visitas de captação, assinatura de autorização de venda.</span>\n          <div class=\"options simnao\" data-name=\"captacaoResposta\" data-error=\"Responda sim ou não.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"captacaoResposta\" id=\"captacao-sim\" value=\"Sim\" />\n              <label for=\"captacao-sim\">Sim</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"captacaoResposta\" id=\"captacao-nao\" value=\"Não\" />\n              <label for=\"captacao-nao\">Não</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"captacaoResposta\">Responda sim ou não.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"captacaoComentario\">Comente sobre</label>\n          <span class=\"field__hint\">Se quiser, dê um pouco mais de contexto sobre sua resposta.</span>\n          <textarea id=\"captacaoComentario\" name=\"captacaoComentario\" rows=\"3\"></textarea>\n        </div>\n      </section>\n\n      <!-- ETAPA 3 -->\n      <section class=\"step hidden\" data-step=\"3\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">03</span>\n        <h2 class=\"step__title\">Mercado de atuação</h2>\n        <p class=\"step__desc\">Onde e com o que você trabalha hoje.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"regioes\">Região(ões) de atuação</label>\n          <span class=\"field__hint\">Cidades, bairros ou eixos onde você já circula e tem rede de contatos.</span>\n          <textarea id=\"regioes\" name=\"regioes\" rows=\"3\" required></textarea>\n          <span class=\"field-error\">Conte um pouco sobre sua região de atuação.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Tipos de imóvel com que mais trabalha</label>\n          <span class=\"field__hint\">Pode marcar mais de uma opção.</span>\n          <div class=\"options\" data-name=\"tiposImovel\" data-error=\"Selecione ao menos uma opção.\" data-multi=\"true\">\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-a\" value=\"Residencial\" />\n              <label for=\"tipo-a\"><span class=\"option__letter\">A</span>Residencial</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-b\" value=\"Comercial\" />\n              <label for=\"tipo-b\"><span class=\"option__letter\">B</span>Comercial</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-c\" value=\"Terrenos\" />\n              <label for=\"tipo-c\"><span class=\"option__letter\">C</span>Terrenos</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-d\" value=\"Rural\" />\n              <label for=\"tipo-d\"><span class=\"option__letter\">D</span>Rural</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"tiposImovel\">Selecione ao menos uma opção.</span>\n        </div>\n      </section>\n\n      <!-- ETAPA 4 -->\n      <section class=\"step hidden\" data-step=\"4\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">04</span>\n        <h2 class=\"step__title\">Disponibilidade</h2>\n        <p class=\"step__desc\">Como você pode se dedicar à rotina de trabalho.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Disponibilidade</label>\n          <div class=\"options\" data-name=\"disponibilidade\" data-error=\"Selecione uma opção.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"disponibilidade\" id=\"disp-a\" value=\"Período integral\" />\n              <label for=\"disp-a\"><span class=\"option__letter\">A</span>Período integral</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"disponibilidade\" id=\"disp-b\" value=\"Meio período\" />\n              <label for=\"disp-b\"><span class=\"option__letter\">B</span>Meio período</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"disponibilidade\" id=\"disp-c\" value=\"Freelancer / por demanda\" />\n              <label for=\"disp-c\"><span class=\"option__letter\">C</span>Freelancer / por demanda</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"disponibilidade\">Selecione uma opção.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Possui veículo próprio?</label>\n          <div class=\"options simnao\" data-name=\"veiculo\" data-error=\"Responda sim ou não.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"veiculo\" id=\"veiculo-sim\" value=\"Sim\" />\n              <label for=\"veiculo-sim\">Sim</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"veiculo\" id=\"veiculo-nao\" value=\"Não\" />\n              <label for=\"veiculo-nao\">Não</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"veiculo\">Responda sim ou não.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"portfolio\">Portfólio / redes sociais</label>\n          <span class=\"field__hint\">Opcional. Instagram, LinkedIn ou site onde acompanhamos seu trabalho.</span>\n          <input type=\"text\" id=\"portfolio\" name=\"portfolio\" placeholder=\"@seuinstagram, linkedin.com/in/..., etc.\" />\n        </div>\n      </section>\n\n      <!-- ETAPA 5 -->\n      <section class=\"step hidden\" data-step=\"5\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">05</span>\n        <h2 class=\"step__title\">Expectativas</h2>\n        <p class=\"step__desc\">Para fecharmos, o que você espera dessa parceria.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"remuneracao\">Modelo de remuneração</label>\n          <span class=\"field__hint\">Seja direto: modelo de comissionamento que considera justo e, se houver, fixo pretendido.</span>\n          <textarea id=\"remuneracao\" name=\"remuneracao\" rows=\"3\" required></textarea>\n          <span class=\"field-error\">Conte o que você espera de remuneração.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"sobreVoce\">Sobre você</label>\n          <span class=\"field__hint\">O que te move no mercado imobiliário, uma captação da qual você se orgulha, e por que a Solua.</span>\n          <textarea id=\"sobreVoce\" name=\"sobreVoce\" rows=\"4\"></textarea>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Autorização LGPD</label>\n          <span class=\"field__hint\">\n            Autorizo a Solua Imóveis a armazenar e tratar meus dados pessoais informados neste formulário,\n            conforme a Lei Geral de Proteção de Dados (LGPD), exclusivamente para fins de recrutamento e\n            contato sobre esta vaga.\n          </span>\n          <div class=\"options simnao\" data-name=\"lgpd\" data-error=\"É necessário autorizar para enviar a candidatura.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"lgpd\" id=\"lgpd-sim\" value=\"Sim\" />\n              <label for=\"lgpd-sim\">Sim</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"lgpd\" id=\"lgpd-nao\" value=\"Não\" />\n              <label for=\"lgpd-nao\">Não</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"lgpd\">É necessário autorizar para enviar a candidatura.</span>\n        </div>\n\n        <div class=\"submit-error\" id=\"submit-error\"></div>\n      </section>\n\n      <!-- As páginas extras configuráveis pelo /admin são inseridas aqui dinamicamente pelo app.js -->\n\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" id=\"btn-back\" type=\"button\">Voltar</button>\n        <button class=\"btn btn-primary\" id=\"btn-next\" type=\"button\">Avançar</button>\n      </div>\n    </form>\n\n    <!-- ===================== TELA DE AGRADECIMENTO ===================== -->\n    <section class=\"thanks hidden\" data-screen=\"thanks\">\n      <div class=\"hero__media\">\n        <img class=\"hero__image\" id=\"thanks-image\" src=\"/images/placeholder.svg\" alt=\"\" />\n        <div class=\"hero__overlay\" id=\"thanks-overlay\"></div>\n        <img class=\"brand-logo hidden\" id=\"thanks-logo\" alt=\"\" />\n      </div>\n      <div class=\"thanks__content\">\n        <div class=\"thanks__check\">✓</div>\n        <h1 class=\"thanks__title\" id=\"thanks-title\">Recebemos sua candidatura!</h1>\n        <p class=\"thanks__message\" id=\"thanks-message\">\n          Obrigado por dedicar seu tempo. Nosso time vai analisar suas respostas e entrar em\n          contato pelo WhatsApp informado em breve.\n        </p>\n        <a class=\"btn btn-primary btn-whatsapp hidden\" id=\"thanks-whatsapp\" href=\"#\" target=\"_blank\" rel=\"noopener\">\n          Enviar mensagem no WhatsApp\n        </a>\n      </div>\n    </section>\n\n  </div>\n\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n";
const STYLES_CSS = "@import url('https://api.fontshare.com/v2/css?f[]=satoshi@400,500,700,900&display=swap');\n\n:root {\n  --azul: #024ba5;\n  --azul-escuro: #012e66;\n  --azul-tint: #e5edf9;\n  --creme: #f2ede6;\n  --creme-escuro: #e2d9c9;\n  --branco: #ffffff;\n  --texto: #0b1b2b;\n  --texto-suave: #5c6773;\n  --erro: #c23b2e;\n  --radius: 14px;\n  font-size: 16px;\n}\n\n* { box-sizing: border-box; }\n\nhtml, body {\n  margin: 0;\n  padding: 0;\n  min-height: 100%;\n}\n\nbody {\n  font-family: \"Satoshi\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  background: var(--creme);\n  color: var(--texto);\n  display: flex;\n  justify-content: center;\n}\n\n#app {\n  width: 100%;\n  max-width: 640px;\n  min-height: 100vh;\n  background: var(--branco);\n  box-shadow: 0 0 40px rgba(2, 75, 165, 0.08);\n  display: flex;\n  flex-direction: column;\n}\n\n/* ---------- Tela de abertura ---------- */\n\n.hero {\n  position: relative;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  color: #fff;\n  background: var(--azul-escuro);\n}\n\n.hero__media {\n  position: absolute;\n  inset: 0;\n  z-index: 0;\n}\n\n.hero__image {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.hero__overlay {\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(180deg, rgba(1,46,102,0.45) 0%, rgba(1,46,102,0.82) 65%, rgba(1,20,46,0.96) 100%);\n}\n\n.hero__overlay.is-hidden { display: none; }\n\n/* ---------- Logo (opcional, sobreposto na foto) ---------- */\n\n.brand-logo {\n  position: absolute;\n  z-index: 3;\n  max-width: 140px;\n  max-height: 56px;\n  object-fit: contain;\n}\n\n.brand-logo.hidden { display: none; }\n\n.brand-logo--top-left { top: 20px; left: 20px; }\n.brand-logo--top-center { top: 20px; left: 50%; transform: translateX(-50%); }\n.brand-logo--top-right { top: 20px; right: 20px; }\n.brand-logo--center { top: 50%; left: 50%; transform: translate(-50%, -50%); }\n.brand-logo--bottom-left { bottom: 20px; left: 20px; }\n.brand-logo--bottom-right { bottom: 20px; right: 20px; }\n\n/* tamanho da logo (a posição \"centro\" usa transform pra centralizar, então o\n   tamanho não pode mexer no transform — só no max-width/max-height mesmo) */\n.brand-logo--size-pequeno { max-width: 90px; max-height: 36px; }\n.brand-logo--size-medio { max-width: 140px; max-height: 56px; }\n.brand-logo--size-grande { max-width: 220px; max-height: 88px; }\n\n.hero__content {\n  position: relative;\n  z-index: 2;\n  margin-top: auto;\n  padding: 40px 28px 48px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n/* posição vertical do bloco de texto sobre a foto (só no celular — no\n   computador o texto já fica sempre centralizado no painel ao lado) */\n.hero__content.text-pos-top { margin-top: 0; margin-bottom: auto; }\n.hero__content.text-pos-center { margin-top: auto; margin-bottom: auto; }\n.hero__content.text-pos-bottom { margin-top: auto; margin-bottom: 0; }\n\n/* alinhamento horizontal do texto (e dos elementos do bloco) */\n.text-align-left { text-align: left; align-items: flex-start; }\n.text-align-center { text-align: center; align-items: center; }\n.text-align-right { text-align: right; align-items: flex-end; }\n\n.hero__title {\n  font-size: 2.1rem;\n  line-height: 1.15;\n  margin: 0;\n  font-weight: 900;\n  letter-spacing: -0.01em;\n}\n\n.hero__title.title-size-small { font-size: 1.6rem; }\n.hero__title.title-size-large { font-size: 2.6rem; }\n\n.hero__subtitle {\n  margin: 0;\n  color: #dfe7f2;\n  font-size: 1rem;\n  line-height: 1.5;\n}\n\n/* ---------- Botões ---------- */\n\n.btn {\n  appearance: none;\n  border: none;\n  border-radius: 999px;\n  padding: 16px 28px;\n  font-size: 1rem;\n  font-weight: 700;\n  cursor: pointer;\n  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;\n  font-family: inherit;\n}\n\n.btn:active { transform: scale(0.98); }\n\n.btn-primary {\n  background: var(--azul);\n  color: #fff;\n  box-shadow: 0 8px 20px rgba(2, 75, 165, 0.35);\n}\n\n.btn-primary:hover { box-shadow: 0 10px 24px rgba(2, 75, 165, 0.45); }\n\n.btn-primary:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n  box-shadow: none;\n}\n\n.btn-ghost {\n  background: transparent;\n  color: var(--texto-suave);\n  padding: 16px 18px;\n}\n\n.hero .btn-primary {\n  width: 100%;\n  background: var(--creme);\n  color: var(--azul-escuro);\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);\n}\n\n.hero .btn-primary:hover { box-shadow: 0 10px 28px rgba(0, 0, 0, 0.3); }\n\n.actions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  margin-top: -12px;\n  padding: 0 24px 40px;\n}\n\n.actions .btn-primary { flex: 1; }\n\n/* ---------- Etapas do formulário ---------- */\n\n.step {\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n  padding: 28px 24px 40px;\n}\n\n.progress {\n  display: flex;\n  gap: 6px;\n  margin-bottom: 22px;\n}\n\n.progress__bar {\n  flex: 1;\n  height: 4px;\n  border-radius: 2px;\n  background: var(--creme-escuro);\n  overflow: hidden;\n}\n\n.progress__bar.is-filled { background: var(--azul); }\n\n.step__eyebrow {\n  color: var(--azul);\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  font-size: 0.8rem;\n  text-transform: uppercase;\n  margin-bottom: 6px;\n}\n\n.step__title {\n  font-size: 1.5rem;\n  margin: 0 0 6px;\n  color: var(--texto);\n  font-weight: 900;\n}\n\n.step__desc {\n  color: var(--texto-suave);\n  margin: 0 0 24px;\n  line-height: 1.5;\n}\n\n.field {\n  margin-bottom: 22px;\n}\n\n.field label.field__label {\n  display: block;\n  font-weight: 700;\n  margin-bottom: 4px;\n  color: var(--texto);\n}\n\n.field__hint {\n  display: block;\n  color: var(--texto-suave);\n  font-size: 0.85rem;\n  margin-bottom: 8px;\n  line-height: 1.4;\n}\n\n.field input[type=\"text\"],\n.field input[type=\"email\"],\n.field input[type=\"tel\"],\n.field textarea {\n  width: 100%;\n  border: 1.5px solid var(--creme-escuro);\n  border-radius: 10px;\n  padding: 13px 14px;\n  font-size: 1rem;\n  font-family: inherit;\n  color: var(--texto);\n  background: var(--branco);\n  transition: border-color 0.15s ease;\n}\n\n.field input:focus,\n.field textarea:focus {\n  outline: none;\n  border-color: var(--azul);\n}\n\n.field textarea {\n  resize: vertical;\n  min-height: 90px;\n}\n\n.field-error {\n  display: none;\n  color: var(--erro);\n  font-size: 0.85rem;\n  margin-top: 6px;\n}\n\n.field.has-error input,\n.field.has-error textarea {\n  border-color: var(--erro);\n}\n\n.field.has-error .field-error { display: block; }\n\n/* opções (radio / checkbox estilo cartão) */\n\n.options {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.option {\n  position: relative;\n}\n\n.option input {\n  position: absolute;\n  opacity: 0;\n  width: 1px;\n  height: 1px;\n}\n\n.option label {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  border: 1.5px solid var(--creme-escuro);\n  border-radius: 10px;\n  padding: 13px 14px;\n  cursor: pointer;\n  transition: border-color 0.15s ease, background 0.15s ease;\n}\n\n.option__letter {\n  flex: 0 0 auto;\n  width: 26px;\n  height: 26px;\n  border-radius: 50%;\n  border: 1.5px solid var(--creme-escuro);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 0.8rem;\n  font-weight: 700;\n  color: var(--texto-suave);\n}\n\n.option input:checked + label {\n  border-color: var(--azul);\n  background: var(--azul-tint);\n}\n\n.option input:checked + label .option__letter {\n  background: var(--azul);\n  border-color: var(--azul);\n  color: #fff;\n}\n\n.option input:focus-visible + label {\n  outline: 2px solid var(--azul);\n  outline-offset: 2px;\n}\n\n/* sim / não em linha */\n\n.simnao {\n  display: flex;\n  gap: 10px;\n}\n\n.simnao .option { flex: 1; }\n.simnao .option label { justify-content: center; }\n.simnao .option__letter { display: none; }\n\n/* ---------- Tela de agradecimento ---------- */\n\n.thanks {\n  position: relative;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  color: #fff;\n  background: var(--azul-escuro);\n}\n\n.thanks__media {\n  position: absolute;\n  inset: 0;\n  z-index: 0;\n}\n\n.thanks__content {\n  position: relative;\n  z-index: 2;\n  margin: auto;\n  padding: 40px 28px;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.thanks__content.text-pos-top { margin: 40px auto auto; }\n.thanks__content.text-pos-center { margin: auto; }\n.thanks__content.text-pos-bottom { margin: auto auto 40px; }\n\n.thanks__check {\n  width: 56px;\n  height: 56px;\n  border-radius: 50%;\n  background: var(--creme);\n  color: var(--azul-escuro);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.6rem;\n  margin-bottom: 6px;\n  font-weight: 900;\n}\n\n.thanks__title {\n  font-size: 1.7rem;\n  margin: 0;\n  font-weight: 900;\n}\n\n.thanks__message {\n  margin: 0;\n  color: #dfe7f2;\n  line-height: 1.55;\n  max-width: 46ch;\n}\n\n.btn-whatsapp {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  margin-top: 8px;\n  background: var(--creme);\n  color: var(--azul-escuro);\n  text-decoration: none;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);\n}\n\n.btn-whatsapp:hover { box-shadow: 0 10px 28px rgba(0, 0, 0, 0.3); }\n\n/* ---------- utilitários ---------- */\n\n.hidden { display: none !important; }\n\n.submit-error {\n  color: var(--erro);\n  background: rgba(194, 59, 46, 0.08);\n  border: 1px solid rgba(194, 59, 46, 0.25);\n  border-radius: 10px;\n  padding: 12px 14px;\n  margin-top: 16px;\n  font-size: 0.9rem;\n  display: none;\n}\n\n.submit-error.is-visible { display: block; }\n\n.spinner {\n  width: 16px;\n  height: 16px;\n  border-radius: 50%;\n  border: 2px solid rgba(255,255,255,0.35);\n  border-top-color: #fff;\n  animation: spin 0.7s linear infinite;\n  display: inline-block;\n  vertical-align: middle;\n  margin-right: 8px;\n}\n\n@keyframes spin { to { transform: rotate(360deg); } }\n\n.honeypot { position: absolute; left: -9999px; top: -9999px; }\n\n/* ---------- Telas maiores (tablet / desktop) ---------- */\n\n@media (min-width: 900px) {\n  body {\n    padding: 48px 24px;\n    align-items: center;\n  }\n\n  #app {\n    max-width: 1000px;\n    min-height: auto;\n    border-radius: 24px;\n    overflow: hidden;\n    box-shadow: 0 30px 80px rgba(2, 75, 165, 0.18);\n  }\n\n  /* tela inicial e agradecimento viram duas colunas: foto + conteúdo */\n  .hero,\n  .thanks {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    min-height: 620px;\n  }\n\n  .hero__media,\n  .thanks__media {\n    position: relative;\n    inset: auto;\n    height: 100%;\n  }\n\n  .hero__content {\n    position: relative;\n    margin-top: 0;\n    height: 100%;\n    justify-content: center;\n    padding: 56px;\n    gap: 20px;\n  }\n\n  .hero__title { font-size: 2.5rem; }\n  .hero__title.title-size-small { font-size: 2rem; }\n  .hero__title.title-size-large { font-size: 3rem; }\n  .hero__subtitle { font-size: 1.05rem; max-width: 40ch; }\n\n  .hero .btn-primary {\n    width: auto;\n    align-self: flex-start;\n    padding: 16px 36px;\n  }\n\n  .thanks__content {\n    height: 100%;\n    margin: 0;\n    padding: 56px;\n  }\n\n  .thanks__message { max-width: 40ch; }\n\n  /* etapas do formulário: card mais largo, conteúdo com leitura confortável */\n  .step {\n    min-height: 560px;\n    max-width: 600px;\n    margin: 0 auto;\n    padding: 56px 0 64px;\n    justify-content: center;\n  }\n\n  .actions {\n    max-width: 600px;\n    margin: -12px auto 0;\n    padding: 0 0 56px;\n  }\n}\n";
const APP_JS = "/**\n * Formulário de candidatura — Solua Imóveis\n *\n * ---------------------------------------------------------------\n * PARA PERSONALIZAR: os valores padrão abaixo (CONFIG) só valem\n * enquanto ninguém salvou nada em Configurações no /admin. Depois de\n * salvar por lá, o que estiver no banco manda — este objeto vira só\n * o \"modo de segurança\" caso o banco esteja vazio ou fora do ar.\n * ---------------------------------------------------------------\n */\nconst CAPA_URL = \"https://drive.google.com/thumbnail?id=1AQSDOAJ0f0w6NtLSyc3UzGU-DSGaUwpz&sz=w1600\";\n\nconst CONFIG = {\n  capa: {\n    image: CAPA_URL,\n    position: \"center\",\n    gradient: true,\n  },\n  logo: {\n    image: \"\",\n    position: \"top-left\",\n    size: \"medio\",\n  },\n  landing: {\n    title: \"Vagas para corretores (as)\",\n    titleSize: \"normal\",\n    subtitle:\n      \"Leva menos de 5 minutos. Conte um pouco sobre sua experiência e a forma como você atua \" +\n      \"no mercado imobiliário para darmos início à conversa.\",\n    buttonLabel: \"Iniciar\",\n    textAlign: \"left\",\n    textPosition: \"bottom\",\n  },\n  thanks: {\n    title: \"Recebemos sua candidatura!\",\n    message:\n      \"Obrigado por dedicar seu tempo. Nosso time vai analisar suas respostas e entrar em \" +\n      \"contato pelo WhatsApp informado em breve.\",\n    textAlign: \"center\",\n    textPosition: \"center\",\n    whatsappNumber: \"\",\n    whatsappMessage: \"Olá! Acabei de enviar minha candidatura pelo site da Solua.\",\n  },\n  extraPages: [],\n};\n\nconst BASE_STEPS = 5;\nlet TOTAL_STEPS = BASE_STEPS;\nlet extraPages = [];\n\n/** Mescla a configuração salva no banco (se houver) por cima dos padrões locais. */\nfunction mergeConfig(saved) {\n  if (!saved || typeof saved !== \"object\") return CONFIG;\n\n  let mergedExtraPages = [];\n  if (Array.isArray(saved.extraPages)) {\n    mergedExtraPages = saved.extraPages;\n  } else if (Array.isArray(saved.extraQuestions) && saved.extraQuestions.length) {\n    // compatibilidade com configs salvas antes de existirem \"páginas extras\"\n    mergedExtraPages = [{ id: \"p1\", title: \"Perguntas extras\", questions: saved.extraQuestions }];\n  }\n\n  return {\n    capa: { ...CONFIG.capa, ...(saved.capa || {}) },\n    logo: { ...CONFIG.logo, ...(saved.logo || {}) },\n    landing: { ...CONFIG.landing, ...(saved.landing || {}) },\n    thanks: { ...CONFIG.thanks, ...(saved.thanks || {}) },\n    extraPages: mergedExtraPages,\n  };\n}\n\nasync function loadConfig() {\n  try {\n    const res = await fetch(\"/api/config\", { cache: \"no-store\" });\n    if (!res.ok) return CONFIG;\n    const data = await res.json();\n    return mergeConfig(data.config);\n  } catch {\n    return CONFIG; // offline ou API fora do ar: segue com os padrões locais\n  }\n}\n\nfunction escapeHtml(value) {\n  const div = document.createElement(\"div\");\n  div.textContent = value == null ? \"\" : String(value);\n  return div.innerHTML;\n}\n\nfunction digitsOnly(value) {\n  return String(value || \"\").replace(/\\D/g, \"\");\n}\n\nfunction setTextAlign(el, align) {\n  el.classList.remove(\"text-align-left\", \"text-align-center\", \"text-align-right\");\n  el.classList.add(`text-align-${[\"left\", \"center\", \"right\"].includes(align) ? align : \"left\"}`);\n}\n\nfunction setTextPosition(el, position) {\n  el.classList.remove(\"text-pos-top\", \"text-pos-center\", \"text-pos-bottom\");\n  el.classList.add(`text-pos-${[\"top\", \"center\", \"bottom\"].includes(position) ? position : \"bottom\"}`);\n}\n\nconst LOGO_POSITIONS = [\"top-left\", \"top-center\", \"top-right\", \"center\", \"bottom-left\", \"bottom-right\"];\nconst LOGO_SIZES = [\"pequeno\", \"medio\", \"grande\"];\n\nfunction applyLogo(imgEl, cfg) {\n  const hasLogo = Boolean(cfg.logo && cfg.logo.image);\n  imgEl.classList.toggle(\"hidden\", !hasLogo);\n  if (!hasLogo) return;\n\n  imgEl.src = cfg.logo.image;\n  LOGO_POSITIONS.forEach((pos) => imgEl.classList.remove(`brand-logo--${pos}`));\n  const position = LOGO_POSITIONS.includes(cfg.logo.position) ? cfg.logo.position : \"top-left\";\n  imgEl.classList.add(`brand-logo--${position}`);\n\n  LOGO_SIZES.forEach((size) => imgEl.classList.remove(`brand-logo--size-${size}`));\n  const size = LOGO_SIZES.includes(cfg.logo.size) ? cfg.logo.size : \"medio\";\n  imgEl.classList.add(`brand-logo--size-${size}`);\n}\n\nfunction applyWhatsappButton(cfg) {\n  const btn = document.getElementById(\"thanks-whatsapp\");\n  const number = digitsOnly(cfg.thanks.whatsappNumber);\n  if (!number) {\n    btn.classList.add(\"hidden\");\n    return;\n  }\n  const text = encodeURIComponent(cfg.thanks.whatsappMessage || \"\");\n  btn.href = `https://wa.me/${number}${text ? `?text=${text}` : \"\"}`;\n  btn.classList.remove(\"hidden\");\n}\n\nfunction applyConfig(cfg) {\n  // se a capa foi removida no admin sem colocar outra no lugar, evita quebrar a imagem no ar\n  const capaImage = cfg.capa.image || CONFIG.capa.image;\n  document.getElementById(\"landing-image\").src = capaImage;\n  document.getElementById(\"landing-image\").style.objectPosition = cfg.capa.position || \"center\";\n  document.getElementById(\"landing-overlay\").classList.toggle(\"is-hidden\", cfg.capa.gradient === false);\n  document.getElementById(\"landing-title\").textContent = cfg.landing.title;\n  document.getElementById(\"landing-subtitle\").textContent = cfg.landing.subtitle;\n  document.getElementById(\"btn-start\").textContent = cfg.landing.buttonLabel;\n  applyLogo(document.getElementById(\"landing-logo\"), cfg);\n\n  const landingContent = document.querySelector(\".hero__content\");\n  setTextAlign(landingContent, cfg.landing.textAlign);\n  setTextPosition(landingContent, cfg.landing.textPosition);\n\n  const titleEl = document.getElementById(\"landing-title\");\n  titleEl.classList.remove(\"title-size-small\", \"title-size-large\");\n  if (cfg.landing.titleSize === \"small\") titleEl.classList.add(\"title-size-small\");\n  if (cfg.landing.titleSize === \"large\") titleEl.classList.add(\"title-size-large\");\n\n  document.getElementById(\"thanks-image\").src = capaImage;\n  document.getElementById(\"thanks-image\").style.objectPosition = cfg.capa.position || \"center\";\n  document.getElementById(\"thanks-overlay\").classList.toggle(\"is-hidden\", cfg.capa.gradient === false);\n  document.getElementById(\"thanks-title\").textContent = cfg.thanks.title;\n  document.getElementById(\"thanks-message\").textContent = cfg.thanks.message;\n  applyLogo(document.getElementById(\"thanks-logo\"), cfg);\n  applyWhatsappButton(cfg);\n\n  const thanksContent = document.querySelector(\".thanks__content\");\n  setTextAlign(thanksContent, cfg.thanks.textAlign);\n  setTextPosition(thanksContent, cfg.thanks.textPosition);\n}\n\n/** HTML de um único campo de pergunta, de acordo com o tipo configurado. */\nfunction renderQuestionField(q) {\n  const name = `extra_${q.id}`;\n  const label = escapeHtml(q.label);\n\n  if (q.type === \"textarea\") {\n    return `<div class=\"field\">\n      <label class=\"field__label\" for=\"${name}\">${label}</label>\n      <textarea id=\"${name}\" name=\"${name}\" rows=\"3\" ${q.required ? \"required\" : \"\"}></textarea>\n      <span class=\"field-error\">Preencha esse campo.</span>\n    </div>`;\n  }\n\n  if (q.type === \"escolha\" || q.type === \"checkbox\") {\n    const inputType = q.type === \"checkbox\" ? \"checkbox\" : \"radio\";\n    const opts = (q.options || [])\n      .map((opt, oi) => {\n        const letter = String.fromCharCode(65 + oi);\n        return `<div class=\"option\">\n          <input type=\"${inputType}\" name=\"${name}\" id=\"${name}-${oi}\" value=\"${escapeHtml(opt)}\" />\n          <label for=\"${name}-${oi}\"><span class=\"option__letter\">${letter}</span>${escapeHtml(opt)}</label>\n        </div>`;\n      })\n      .join(\"\");\n    const errMsg = q.type === \"checkbox\" ? \"Selecione ao menos uma opção.\" : \"Selecione uma opção.\";\n    return `<div class=\"field\">\n      <label class=\"field__label\">${label}</label>\n      <div class=\"options\" data-name=\"${name}\" data-error=\"${errMsg}\" ${q.required ? \"\" : 'data-optional=\"true\"'}>${opts}</div>\n      <span class=\"field-error\" data-for=\"${name}\">${errMsg}</span>\n    </div>`;\n  }\n\n  if (q.type === \"simnao\") {\n    return `<div class=\"field\">\n      <label class=\"field__label\">${label}</label>\n      <div class=\"options simnao\" data-name=\"${name}\" data-error=\"Responda sim ou não.\" ${q.required ? \"\" : 'data-optional=\"true\"'}>\n        <div class=\"option\">\n          <input type=\"radio\" name=\"${name}\" id=\"${name}-sim\" value=\"Sim\" />\n          <label for=\"${name}-sim\">Sim</label>\n        </div>\n        <div class=\"option\">\n          <input type=\"radio\" name=\"${name}\" id=\"${name}-nao\" value=\"Não\" />\n          <label for=\"${name}-nao\">Não</label>\n        </div>\n      </div>\n      <span class=\"field-error\" data-for=\"${name}\">Responda sim ou não.</span>\n    </div>`;\n  }\n\n  return `<div class=\"field\">\n    <label class=\"field__label\" for=\"${name}\">${label}</label>\n    <input type=\"text\" id=\"${name}\" name=\"${name}\" ${q.required ? \"required\" : \"\"} />\n    <span class=\"field-error\">Preencha esse campo.</span>\n  </div>`;\n}\n\n/** Cria uma etapa (página) do formulário para cada página extra configurada. */\nfunction buildExtraPages(pages) {\n  document.querySelectorAll(\".step[data-extra-page]\").forEach((el) => el.remove());\n  if (!pages.length) return;\n\n  const form = document.getElementById(\"form\");\n  const actions = form.querySelector(\".actions\");\n\n  pages.forEach((page, i) => {\n    const stepNumber = BASE_STEPS + i + 1;\n    const section = document.createElement(\"section\");\n    section.className = \"step hidden\";\n    section.dataset.step = String(stepNumber);\n    section.dataset.extraPage = \"true\";\n    section.innerHTML = `\n      <div class=\"progress\"></div>\n      <span class=\"step__eyebrow\">${String(stepNumber).padStart(2, \"0\")}</span>\n      <h2 class=\"step__title\">${escapeHtml(page.title || \"Mais perguntas\")}</h2>\n      <div class=\"extra-page-fields\">\n        ${(page.questions || []).map(renderQuestionField).join(\"\")}\n      </div>\n    `;\n    form.insertBefore(section, actions);\n  });\n}\n\nfunction buildProgressBars() {\n  document.querySelectorAll(\".progress\").forEach((container) => {\n    const stepEl = container.closest(\".step\");\n    const currentStep = Number(stepEl.dataset.step);\n    container.innerHTML = \"\";\n    for (let i = 1; i <= TOTAL_STEPS; i++) {\n      const bar = document.createElement(\"div\");\n      bar.className = \"progress__bar\" + (i <= currentStep ? \" is-filled\" : \"\");\n      container.appendChild(bar);\n    }\n  });\n}\n\nfunction showScreen(name) {\n  document.querySelectorAll(\"[data-screen]\").forEach((el) => {\n    el.classList.toggle(\"hidden\", el.dataset.screen !== name);\n  });\n  const form = document.getElementById(\"form\");\n  form.classList.toggle(\"hidden\", name !== \"form\");\n  window.scrollTo(0, 0);\n}\n\nlet currentStep = 1;\n\nfunction showStep(n) {\n  currentStep = n;\n  document.querySelectorAll(\".step\").forEach((el) => {\n    el.classList.toggle(\"hidden\", Number(el.dataset.step) !== n);\n  });\n  document.getElementById(\"btn-back\").style.visibility = n === 1 ? \"hidden\" : \"visible\";\n  document.getElementById(\"btn-next\").textContent = n === TOTAL_STEPS ? \"Enviar\" : \"Avançar\";\n  window.scrollTo(0, 0);\n}\n\nfunction setFieldError(fieldEl, hasError) {\n  fieldEl.classList.toggle(\"has-error\", hasError);\n}\n\n/** Valida a etapa atual; retorna true se pode avançar. */\nfunction validateStep(n) {\n  let valid = true;\n  const stepEl = document.querySelector(`.step[data-step=\"${n}\"]`);\n  if (!stepEl) return true;\n\n  // inputs de texto/textarea simples com atributo required\n  stepEl.querySelectorAll(\"input[required], textarea[required]\").forEach((input) => {\n    const fieldEl = input.closest(\".field\");\n    const ok = input.value.trim().length > 0;\n    if (input.type === \"email\" && ok) {\n      const emailOk = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(input.value.trim());\n      setFieldError(fieldEl, !emailOk);\n      if (!emailOk) valid = false;\n      return;\n    }\n    setFieldError(fieldEl, !ok);\n    if (!ok) valid = false;\n  });\n\n  // grupos de opções (radio / checkbox) — obrigatórios, a menos que marcados como opcionais\n  stepEl.querySelectorAll(\".options[data-name]\").forEach((group) => {\n    if (group.dataset.optional === \"true\") return;\n\n    const name = group.dataset.name;\n    const checked = group.querySelectorAll(`input[name=\"${name}\"]:checked`);\n    const errorEl = stepEl.querySelector(`.field-error[data-for=\"${name}\"]`);\n    const ok = checked.length > 0;\n    if (!ok) {\n      valid = false;\n      if (errorEl) errorEl.style.display = \"block\";\n    } else if (errorEl) {\n      errorEl.style.display = \"none\";\n    }\n  });\n\n  return valid;\n}\n\nfunction allExtraQuestions() {\n  return extraPages.flatMap((p) => p.questions || []);\n}\n\nfunction collectExtraRespostas(fd) {\n  const result = {};\n  allExtraQuestions().forEach((q) => {\n    const name = `extra_${q.id}`;\n    if (q.type === \"checkbox\") {\n      const vals = fd.getAll(name);\n      if (vals.length) result[q.label] = vals.join(\", \");\n      return;\n    }\n    const val = fd.get(name);\n    if (val) result[q.label] = val;\n  });\n  return result;\n}\n\nfunction collectFormData() {\n  const form = document.getElementById(\"form\");\n  const fd = new FormData(form);\n\n  return {\n    nome: fd.get(\"nome\") || \"\",\n    email: fd.get(\"email\") || \"\",\n    whatsapp: fd.get(\"whatsapp\") || \"\",\n    cidade: fd.get(\"cidade\") || \"\",\n    creci: fd.get(\"creci\") || \"\",\n    experiencia: fd.get(\"experiencia\") || \"\",\n    captacao: buildCaptacaoText(fd),\n    regioes: fd.get(\"regioes\") || \"\",\n    tiposImovel: fd.getAll(\"tiposImovel\"),\n    disponibilidade: fd.get(\"disponibilidade\") || \"\",\n    veiculo: fd.get(\"veiculo\") || \"\",\n    portfolio: fd.get(\"portfolio\") || \"\",\n    remuneracao: fd.get(\"remuneracao\") || \"\",\n    sobreVoce: fd.get(\"sobreVoce\") || \"\",\n    lgpd: fd.get(\"lgpd\") || \"\",\n    extraRespostas: collectExtraRespostas(fd),\n    website: fd.get(\"website\") || \"\", // honeypot\n  };\n}\n\nfunction buildCaptacaoText(fd) {\n  const resposta = fd.get(\"captacaoResposta\") || \"\";\n  const comentario = (fd.get(\"captacaoComentario\") || \"\").trim();\n  return comentario ? `${resposta} — ${comentario}` : resposta;\n}\n\nasync function submitForm() {\n  const btnNext = document.getElementById(\"btn-next\");\n  const errorBox = document.getElementById(\"submit-error\");\n  errorBox.classList.remove(\"is-visible\");\n  errorBox.textContent = \"\";\n\n  const original = btnNext.innerHTML;\n  btnNext.disabled = true;\n  btnNext.innerHTML = '<span class=\"spinner\"></span>Enviando…';\n\n  try {\n    const res = await fetch(\"/api/submit\", {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify(collectFormData()),\n    });\n    const data = await res.json().catch(() => ({}));\n\n    if (!res.ok || !data.ok) {\n      throw new Error(data.error || \"Não foi possível enviar sua candidatura. Tente novamente.\");\n    }\n\n    showScreen(\"thanks\");\n  } catch (err) {\n    errorBox.textContent = err.message || \"Erro inesperado. Tente novamente em instantes.\";\n    errorBox.classList.add(\"is-visible\");\n    errorBox.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n  } finally {\n    btnNext.disabled = false;\n    btnNext.innerHTML = original;\n  }\n}\n\nasync function init() {\n  const cfg = await loadConfig();\n\n  extraPages = cfg.extraPages || [];\n  TOTAL_STEPS = BASE_STEPS + extraPages.length;\n\n  applyConfig(cfg);\n  buildExtraPages(extraPages);\n  buildProgressBars();\n\n  // usado só pela pré-visualização no /admin: pula direto pro final, sem preencher nada\n  const previewSkip = new URLSearchParams(window.location.search).get(\"preview_skip\") === \"1\";\n  if (previewSkip) {\n    showScreen(\"thanks\");\n  } else {\n    showStep(1);\n  }\n\n  document.getElementById(\"btn-start\").addEventListener(\"click\", () => {\n    showScreen(\"form\");\n  });\n\n  document.getElementById(\"btn-back\").addEventListener(\"click\", () => {\n    if (currentStep > 1) showStep(currentStep - 1);\n  });\n\n  document.getElementById(\"btn-next\").addEventListener(\"click\", async () => {\n    if (!validateStep(currentStep)) return;\n\n    if (currentStep < TOTAL_STEPS) {\n      showStep(currentStep + 1);\n    } else {\n      await submitForm();\n    }\n  });\n\n  // Enter não deve enviar o form prematuramente (exceto em textarea, que já quebra linha)\n  document.getElementById(\"form\").addEventListener(\"submit\", (e) => e.preventDefault());\n}\n\ndocument.addEventListener(\"DOMContentLoaded\", init);\n";
const PLACEHOLDER_SVG = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 600\" width=\"800\" height=\"600\">\n  <rect width=\"800\" height=\"600\" fill=\"#024ba5\"/>\n</svg>\n";
const ADMIN_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Painel — Solua Imóveis</title>\n  <meta name=\"theme-color\" content=\"#024ba5\" />\n  <link rel=\"preconnect\" href=\"https://api.fontshare.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"/styles.css\" />\n  <style>\n    body { justify-content: center; align-items: flex-start; padding: 32px 16px; }\n    #admin { width: 100%; max-width: 1200px; background: var(--branco); border-radius: 14px; box-shadow: 0 0 40px rgba(2,75,165,0.08); padding: 28px; }\n    .admin__header { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 20px; }\n    .admin__title { font-size: 1.4rem; font-weight: 900; color: var(--texto); margin: 0; }\n    .admin__gate { max-width: 360px; margin: 60px auto; text-align: center; }\n    .admin__gate input { width: 100%; margin-bottom: 12px; }\n    .admin__count { color: var(--texto-suave); font-size: 0.9rem; }\n\n    .tabs { display: flex; gap: 8px; margin-bottom: 24px; border-bottom: 1.5px solid var(--creme-escuro); flex-wrap: wrap; }\n    .tab-btn {\n      background: none; border: none; padding: 10px 4px; margin-bottom: -1.5px;\n      font-family: inherit; font-weight: 700; font-size: 0.95rem; color: var(--texto-suave);\n      cursor: pointer; border-bottom: 2.5px solid transparent;\n    }\n    .tab-btn.is-active { color: var(--azul); border-bottom-color: var(--azul); }\n    .tab-panel { display: none; }\n    .tab-panel.is-active { display: block; }\n\n    table { border-collapse: collapse; width: 100%; font-size: 0.85rem; }\n    thead th {\n      text-align: left; background: var(--azul-tint); color: var(--azul-escuro);\n      padding: 10px 12px; position: sticky; top: 0; white-space: nowrap; font-weight: 700;\n    }\n    tbody td { padding: 10px 12px; border-bottom: 1px solid var(--creme-escuro); vertical-align: top; }\n    tbody tr:hover { background: var(--creme); }\n    .table-wrap { overflow-x: auto; border: 1px solid var(--creme-escuro); border-radius: 10px; }\n    .cell-wrap { max-width: 260px; white-space: pre-wrap; }\n    .error-msg { color: var(--erro); margin-top: 10px; font-size: 0.9rem; display: none; }\n    .error-msg.is-visible { display: block; }\n    .success-msg { color: var(--azul); margin-top: 10px; font-size: 0.9rem; display: none; }\n    .success-msg.is-visible { display: block; }\n    .toolbar { display: flex; gap: 10px; }\n    .btn-small { padding: 10px 18px; font-size: 0.9rem; }\n    .btn-delete {\n      background: none; border: 1.5px solid var(--erro); color: var(--erro);\n      border-radius: 8px; padding: 6px 12px; font-size: 0.8rem; font-weight: 700;\n      cursor: pointer; white-space: nowrap;\n    }\n    .btn-delete:hover { background: rgba(194, 59, 46, 0.08); }\n    .btn-delete:disabled { opacity: 0.5; cursor: not-allowed; }\n    .btn-icon {\n      background: var(--creme); border: 1.5px solid var(--creme-escuro); color: var(--texto);\n      border-radius: 8px; width: 32px; height: 32px; font-size: 1rem; cursor: pointer; line-height: 1;\n    }\n    .btn-icon:hover { border-color: var(--azul); color: var(--azul); }\n    .btn-icon:disabled { opacity: 0.35; cursor: not-allowed; }\n\n    .settings-section { max-width: 640px; margin-bottom: 32px; }\n    .settings-section h2 { font-size: 1.05rem; font-weight: 900; color: var(--texto); margin: 0 0 4px; }\n    .settings-section .field__hint { margin-bottom: 16px; }\n    .settings-row { display: flex; gap: 16px; }\n    .settings-row .field { flex: 1; }\n    .settings-select {\n      width: 100%; border: 1.5px solid var(--creme-escuro); border-radius: 10px;\n      padding: 13px 14px; font-size: 1rem; font-family: inherit; color: var(--texto); background: var(--branco);\n    }\n    .field-checkbox { display: flex; align-items: center; gap: 8px; font-weight: 700; cursor: pointer; }\n    .field-checkbox input { width: auto; }\n\n    /* upload de imagem */\n    .image-upload { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }\n    .image-upload__preview {\n      width: 96px; height: 96px; object-fit: cover; border-radius: 10px; background: var(--creme);\n      border: 1.5px solid var(--creme-escuro);\n    }\n    .image-upload__preview.is-empty { opacity: 0.35; }\n    .image-upload__actions { display: flex; flex-direction: column; gap: 8px; }\n    .image-upload__pick {\n      display: inline-block; cursor: pointer; text-align: center;\n    }\n    .image-upload__status { font-size: 0.8rem; color: var(--texto-suave); }\n    .image-upload__status.is-error { color: var(--erro); }\n\n    /* páginas extras */\n    .extra-page {\n      border: 1.5px solid var(--creme-escuro); border-radius: 12px; padding: 16px; margin-bottom: 16px; background: var(--creme);\n    }\n    .extra-page__header { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }\n    .extra-page-title { flex: 1; font-weight: 700; background: var(--branco); }\n    .extra-page__move { display: flex; gap: 4px; }\n\n    .extra-q {\n      border: 1.5px solid var(--creme-escuro); border-radius: 10px; padding: 14px; margin-bottom: 10px; background: var(--branco);\n    }\n    .extra-q__row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin-bottom: 8px; }\n    .extra-q__move { display: flex; gap: 4px; }\n    .extra-q-label { flex: 1; min-width: 160px; }\n    .extra-q-type { width: auto; min-width: 150px; }\n    .extra-q__required { display: flex; align-items: center; gap: 6px; font-size: 0.85rem; color: var(--texto-suave); white-space: nowrap; }\n    .extra-q-options { width: 100%; margin-top: 4px; min-height: 60px; }\n    .btn-add-question, .btn-add-page {\n      background: none; border: 1.5px dashed var(--azul); color: var(--azul);\n      border-radius: 10px; padding: 12px; width: 100%; font-weight: 700; cursor: pointer; font-family: inherit;\n    }\n    .btn-add-question:hover, .btn-add-page:hover { background: var(--azul-tint); }\n\n    /* visão geral de páginas */\n    .pages-overview { list-style: none; margin: 0; padding: 0; max-width: 480px; }\n    .pages-overview li {\n      display: flex; align-items: center; gap: 12px; padding: 12px 14px; border: 1.5px solid var(--creme-escuro);\n      border-radius: 10px; margin-bottom: 8px; background: var(--creme);\n    }\n    .pages-overview .page-badge {\n      flex: 0 0 auto; width: 28px; height: 28px; border-radius: 50%; background: var(--azul); color: #fff;\n      display: flex; align-items: center; justify-content: center; font-size: 0.75rem; font-weight: 700;\n    }\n    .pages-overview .page-name { font-weight: 700; flex: 1; }\n    .pages-overview .page-tag { color: var(--texto-suave); font-size: 0.8rem; }\n    .pages-overview li.is-fixed { opacity: 0.75; }\n    .pages-overview li.is-dragging { border-color: var(--azul); box-shadow: 0 6px 16px rgba(2,75,165,0.18); }\n    .drag-handle {\n      flex: 0 0 auto; cursor: grab; color: var(--texto-suave); font-size: 1.1rem; padding: 4px;\n      touch-action: none; user-select: none;\n    }\n    .drag-handle--disabled { cursor: default; opacity: 0.3; }\n\n    /* pré-visualização */\n    .preview-toolbar { display: flex; gap: 10px; margin-bottom: 14px; align-items: center; }\n    .preview-frame-wrap {\n      border: 1.5px solid var(--creme-escuro); border-radius: 12px; overflow: hidden; height: 80vh; max-height: 900px;\n    }\n    .preview-frame-wrap iframe { width: 100%; height: 100%; border: none; }\n  </style>\n</head>\n<body>\n  <div id=\"admin\">\n    <div class=\"admin__gate\" id=\"gate\">\n      <h1 class=\"admin__title\" style=\"margin-bottom: 8px;\">Área restrita</h1>\n      <p class=\"field__hint\" style=\"margin-bottom: 16px;\">Informe o token de administrador para entrar.</p>\n      <input type=\"password\" id=\"token-input\" placeholder=\"Token de administrador\" autofocus />\n      <button class=\"btn btn-primary btn-small\" id=\"btn-enter\" type=\"button\" style=\"width:100%;\">Entrar</button>\n      <p class=\"error-msg\" id=\"gate-error\">Token inválido.</p>\n    </div>\n\n    <div id=\"content\" class=\"hidden\">\n      <div class=\"tabs\">\n        <button class=\"tab-btn is-active\" type=\"button\" data-tab=\"candidaturas\">Candidaturas</button>\n        <button class=\"tab-btn\" type=\"button\" data-tab=\"paginas\">Páginas</button>\n        <button class=\"tab-btn\" type=\"button\" data-tab=\"config\">Configurações</button>\n        <button class=\"tab-btn\" type=\"button\" data-tab=\"preview\">Visualizar</button>\n      </div>\n\n      <!-- ===================== ABA: CANDIDATURAS ===================== -->\n      <div class=\"tab-panel is-active\" id=\"tab-candidaturas\">\n        <div class=\"admin__header\">\n          <h1 class=\"admin__title\">Candidaturas recebidas</h1>\n          <div class=\"toolbar\">\n            <span class=\"admin__count\" id=\"count\"></span>\n            <button class=\"btn btn-ghost btn-small\" id=\"btn-refresh\" type=\"button\">Atualizar</button>\n            <button class=\"btn btn-primary btn-small\" id=\"btn-csv\" type=\"button\">Exportar CSV</button>\n          </div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Data</th>\n                <th>Nome</th>\n                <th>E-mail</th>\n                <th>WhatsApp</th>\n                <th>Cidade/Estado</th>\n                <th>CRECI</th>\n                <th>Experiência</th>\n                <th>Captação</th>\n                <th>Regiões</th>\n                <th>Tipos de imóvel</th>\n                <th>Disponibilidade</th>\n                <th>Veículo</th>\n                <th>Portfólio</th>\n                <th>Remuneração</th>\n                <th>Sobre você</th>\n                <th>LGPD</th>\n                <th>Perguntas extras</th>\n                <th>Ações</th>\n              </tr>\n            </thead>\n            <tbody id=\"rows\"></tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- ===================== ABA: PÁGINAS (visão geral) ===================== -->\n      <div class=\"tab-panel\" id=\"tab-paginas\">\n        <h1 class=\"admin__title\" style=\"margin-bottom: 8px;\">Páginas do formulário</h1>\n        <p class=\"field__hint\" style=\"margin-bottom: 20px;\">\n          Nessa ordem que a pessoa candidata vê. As etapas 01–05 são fixas e não têm como reordenar.\n          Arraste as páginas extras (ícone ⠿) pra cima ou pra baixo pra mudar a ordem delas.\n        </p>\n        <ul class=\"pages-overview\" id=\"pages-overview\"></ul>\n        <div class=\"toolbar\" style=\"margin-top: 16px;\">\n          <button class=\"btn btn-primary btn-small\" id=\"btn-save-pages-order\" type=\"button\">Salvar ordem</button>\n        </div>\n        <p class=\"error-msg\" id=\"pages-error\"></p>\n        <p class=\"success-msg\" id=\"pages-success\">Salvo!</p>\n      </div>\n\n      <!-- ===================== ABA: CONFIGURAÇÕES ===================== -->\n      <div class=\"tab-panel\" id=\"tab-config\">\n        <h1 class=\"admin__title\" style=\"margin-bottom: 20px;\">Configurações do site</h1>\n\n        <div class=\"settings-section\">\n          <h2>Capa</h2>\n          <p class=\"field__hint\">Foto usada na tela inicial e na de agradecimento.</p>\n          <div class=\"field\">\n            <label class=\"field__label\">Imagem</label>\n            <div class=\"image-upload\">\n              <img class=\"image-upload__preview is-empty\" id=\"cfg-capa-preview\" alt=\"\" />\n              <div class=\"image-upload__actions\">\n                <label class=\"btn btn-ghost btn-small image-upload__pick\">\n                  Escolher foto\n                  <input type=\"file\" accept=\"image/*\" id=\"cfg-capa-file\" class=\"hidden\" />\n                </label>\n                <button type=\"button\" class=\"btn-delete\" id=\"cfg-capa-remove\">Remover</button>\n              </div>\n              <span class=\"image-upload__status\" id=\"cfg-capa-status\"></span>\n            </div>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-capa-position\">Posição da imagem</label>\n            <select class=\"settings-select\" id=\"cfg-capa-position\">\n              <option value=\"top\">Topo</option>\n              <option value=\"center\">Centro</option>\n              <option value=\"bottom\">Base</option>\n            </select>\n          </div>\n          <div class=\"field\">\n            <label class=\"field-checkbox\">\n              <input type=\"checkbox\" id=\"cfg-capa-gradient\" checked />\n              Mostrar gradiente escuro sobre a foto (celular e computador)\n            </label>\n            <span class=\"field__hint\">Desligue se quiser a foto sem nenhum escurecimento por cima.</span>\n          </div>\n        </div>\n\n        <div class=\"settings-section\">\n          <h2>Logo</h2>\n          <p class=\"field__hint\">Opcional. Aparece sobre a foto, na tela inicial e na de agradecimento.</p>\n          <div class=\"field\">\n            <label class=\"field__label\">Imagem da logo</label>\n            <div class=\"image-upload\">\n              <img class=\"image-upload__preview is-empty\" id=\"cfg-logo-preview\" alt=\"\" />\n              <div class=\"image-upload__actions\">\n                <label class=\"btn btn-ghost btn-small image-upload__pick\">\n                  Escolher logo\n                  <input type=\"file\" accept=\"image/*\" id=\"cfg-logo-file\" class=\"hidden\" />\n                </label>\n                <button type=\"button\" class=\"btn-delete\" id=\"cfg-logo-remove\">Remover</button>\n              </div>\n              <span class=\"image-upload__status\" id=\"cfg-logo-status\"></span>\n            </div>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-logo-position\">Posição da logo</label>\n            <select class=\"settings-select\" id=\"cfg-logo-position\">\n              <option value=\"top-left\">Superior esquerda</option>\n              <option value=\"top-center\">Superior centro</option>\n              <option value=\"top-right\">Superior direita</option>\n              <option value=\"center\">Centro</option>\n              <option value=\"bottom-left\">Inferior esquerda</option>\n              <option value=\"bottom-right\">Inferior direita</option>\n            </select>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-logo-size\">Tamanho da logo</label>\n            <select class=\"settings-select\" id=\"cfg-logo-size\">\n              <option value=\"pequeno\">Pequeno</option>\n              <option value=\"medio\">Médio</option>\n              <option value=\"grande\">Grande</option>\n            </select>\n          </div>\n        </div>\n\n        <div class=\"settings-section\">\n          <h2>Tela inicial</h2>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-title\">Título</label>\n            <input type=\"text\" id=\"cfg-landing-title\" />\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-title-size\">Tamanho do título</label>\n            <select class=\"settings-select\" id=\"cfg-landing-title-size\">\n              <option value=\"small\">Pequeno</option>\n              <option value=\"normal\">Normal</option>\n              <option value=\"large\">Grande</option>\n            </select>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-subtitle\">Subtítulo</label>\n            <textarea id=\"cfg-landing-subtitle\" rows=\"3\"></textarea>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-button\">Texto do botão</label>\n            <input type=\"text\" id=\"cfg-landing-button\" />\n          </div>\n          <div class=\"settings-row\">\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"cfg-landing-align\">Alinhamento do texto</label>\n              <select class=\"settings-select\" id=\"cfg-landing-align\">\n                <option value=\"left\">Esquerda</option>\n                <option value=\"center\">Centro</option>\n                <option value=\"right\">Direita</option>\n              </select>\n            </div>\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"cfg-landing-pos\">Posição do texto (celular)</label>\n              <select class=\"settings-select\" id=\"cfg-landing-pos\">\n                <option value=\"top\">Topo</option>\n                <option value=\"center\">Centro</option>\n                <option value=\"bottom\">Base</option>\n              </select>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"settings-section\">\n          <h2>Tela de agradecimento</h2>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-thanks-title\">Título</label>\n            <input type=\"text\" id=\"cfg-thanks-title\" />\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-thanks-message\">Mensagem</label>\n            <textarea id=\"cfg-thanks-message\" rows=\"3\"></textarea>\n          </div>\n          <div class=\"settings-row\">\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"cfg-thanks-align\">Alinhamento do texto</label>\n              <select class=\"settings-select\" id=\"cfg-thanks-align\">\n                <option value=\"left\">Esquerda</option>\n                <option value=\"center\">Centro</option>\n                <option value=\"right\">Direita</option>\n              </select>\n            </div>\n            <div class=\"field\">\n              <label class=\"field__label\" for=\"cfg-thanks-pos\">Posição do texto (celular)</label>\n              <select class=\"settings-select\" id=\"cfg-thanks-pos\">\n                <option value=\"top\">Topo</option>\n                <option value=\"center\">Centro</option>\n                <option value=\"bottom\">Base</option>\n              </select>\n            </div>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-thanks-whats-number\">Número do WhatsApp (com DDD e país)</label>\n            <span class=\"field__hint\">Só números, ex.: 5511999999999. Deixe em branco pra não mostrar o botão.</span>\n            <input type=\"text\" id=\"cfg-thanks-whats-number\" placeholder=\"5511999999999\" />\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-thanks-whats-message\">Mensagem pronta do WhatsApp (opcional)</label>\n            <input type=\"text\" id=\"cfg-thanks-whats-message\" placeholder=\"Olá! Acabei de enviar minha candidatura...\" />\n          </div>\n        </div>\n\n        <div class=\"settings-section\" style=\"max-width: 720px;\">\n          <h2>Páginas extras</h2>\n          <p class=\"field__hint\">\n            Cada página vira uma etapa nova no formulário, na ordem que aparecem aqui (depois da 05).\n            Use as setas pra reordenar páginas e perguntas.\n          </p>\n          <div id=\"extra-pages-editor\"></div>\n          <button class=\"btn-add-page\" type=\"button\" id=\"btn-add-page\">+ Nova página</button>\n        </div>\n\n        <button class=\"btn btn-primary\" id=\"btn-save-config\" type=\"button\">Salvar configurações</button>\n        <p class=\"error-msg\" id=\"config-error\"></p>\n        <p class=\"success-msg\" id=\"config-success\">Salvo!</p>\n      </div>\n\n      <!-- ===================== ABA: VISUALIZAR ===================== -->\n      <div class=\"tab-panel\" id=\"tab-preview\">\n        <h1 class=\"admin__title\" style=\"margin-bottom: 14px;\">Visualizar o formulário</h1>\n        <div class=\"preview-toolbar\">\n          <button class=\"btn btn-ghost btn-small\" id=\"btn-preview-refresh\" type=\"button\">Reiniciar (do começo)</button>\n          <button class=\"btn btn-ghost btn-small\" id=\"btn-preview-skip\" type=\"button\">Pular pro final (sem responder)</button>\n          <a class=\"btn btn-ghost btn-small\" id=\"btn-preview-newtab\" href=\"/\" target=\"_blank\" rel=\"noopener\">Abrir em nova aba</a>\n        </div>\n        <div class=\"preview-frame-wrap\">\n          <iframe id=\"preview-frame\" title=\"Pré-visualização do formulário\"></iframe>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    const STORAGE_KEY = \"solua_admin_token\";\n    let currentRows = [];\n    let extraPagesDraft = [];\n\n    // Valores padrão exibidos enquanto nada foi salvo em Configurações ainda\n    // (mesmos valores hoje fixos em public/app.js).\n    const DEFAULT_CONFIG = {\n      capa: {\n        image: \"https://drive.google.com/thumbnail?id=1AQSDOAJ0f0w6NtLSyc3UzGU-DSGaUwpz&sz=w1600\",\n        position: \"center\",\n        gradient: true,\n      },\n      logo: {\n        image: \"\",\n        position: \"top-left\",\n        size: \"medio\",\n      },\n      landing: {\n        title: \"Vagas para corretores (as)\",\n        titleSize: \"normal\",\n        subtitle:\n          \"Leva menos de 5 minutos. Conte um pouco sobre sua experiência e a forma como você atua \" +\n          \"no mercado imobiliário para darmos início à conversa.\",\n        buttonLabel: \"Iniciar\",\n        textAlign: \"left\",\n        textPosition: \"bottom\",\n      },\n      thanks: {\n        title: \"Recebemos sua candidatura!\",\n        message:\n          \"Obrigado por dedicar seu tempo. Nosso time vai analisar suas respostas e entrar em \" +\n          \"contato pelo WhatsApp informado em breve.\",\n        textAlign: \"center\",\n        textPosition: \"center\",\n        whatsappNumber: \"\",\n        whatsappMessage: \"Olá! Acabei de enviar minha candidatura pelo site da Solua.\",\n      },\n      extraPages: [],\n    };\n\n    const BUILTIN_STEPS = [\n      \"01 · Seus dados\",\n      \"02 · Dados profissionais\",\n      \"03 · Mercado de atuação\",\n      \"04 · Disponibilidade\",\n      \"05 · Expectativas\",\n    ];\n\n    function fmtDate(iso) {\n      try {\n        return new Date(iso).toLocaleString(\"pt-BR\", { dateStyle: \"short\", timeStyle: \"short\" });\n      } catch {\n        return iso;\n      }\n    }\n\n    function esc(value) {\n      const div = document.createElement(\"div\");\n      div.textContent = value == null ? \"\" : String(value);\n      return div.innerHTML;\n    }\n\n    function fmtExtraRespostas(json) {\n      if (!json) return \"\";\n      try {\n        const obj = JSON.parse(json);\n        return Object.entries(obj)\n          .map(([label, valor]) => `${label}: ${valor}`)\n          .join(\"\\n\");\n      } catch {\n        return \"\";\n      }\n    }\n\n    function renderRows(rows) {\n      currentRows = rows;\n      document.getElementById(\"count\").textContent = rows.length + \" candidatura(s)\";\n      document.getElementById(\"rows\").innerHTML = rows\n        .map(\n          (r) => `<tr>\n            <td>${esc(fmtDate(r.criado_em))}</td>\n            <td>${esc(r.nome)}</td>\n            <td>${esc(r.email)}</td>\n            <td>${esc(r.whatsapp)}</td>\n            <td>${esc(r.cidade)}</td>\n            <td>${esc(r.creci)}</td>\n            <td>${esc(r.experiencia)}</td>\n            <td class=\"cell-wrap\">${esc(r.captacao)}</td>\n            <td class=\"cell-wrap\">${esc(r.regioes)}</td>\n            <td>${esc(r.tipos_imovel)}</td>\n            <td>${esc(r.disponibilidade)}</td>\n            <td>${esc(r.veiculo)}</td>\n            <td class=\"cell-wrap\">${esc(r.portfolio)}</td>\n            <td class=\"cell-wrap\">${esc(r.remuneracao)}</td>\n            <td class=\"cell-wrap\">${esc(r.sobre_voce)}</td>\n            <td>${esc(r.lgpd)}</td>\n            <td class=\"cell-wrap\">${esc(fmtExtraRespostas(r.extra_respostas))}</td>\n            <td><button class=\"btn-delete\" type=\"button\" data-delete-id=\"${esc(r.id)}\">Excluir</button></td>\n          </tr>`\n        )\n        .join(\"\");\n    }\n\n    async function loadData(token) {\n      const res = await fetch(\"/admin/data\", { headers: { \"x-admin-token\": token }, cache: \"no-store\" });\n      if (!res.ok) {\n        throw new Error(res.status === 401 ? \"Token inválido.\" : \"Erro ao carregar dados.\");\n      }\n      const data = await res.json();\n      return data.rows || [];\n    }\n\n    async function deleteRow(id, btn) {\n      const nome = currentRows.find((r) => String(r.id) === String(id))?.nome || \"essa candidatura\";\n      if (!confirm(`Excluir \"${nome}\"? Essa ação não pode ser desfeita.`)) return;\n\n      const token = sessionStorage.getItem(STORAGE_KEY);\n      btn.disabled = true;\n      btn.textContent = \"Excluindo…\";\n\n      try {\n        const res = await fetch(`/admin/data/${encodeURIComponent(id)}`, {\n          method: \"DELETE\",\n          headers: { \"x-admin-token\": token },\n        });\n        const data = await res.json().catch(() => ({}));\n        if (!res.ok || !data.ok) {\n          throw new Error(data.error || \"Não foi possível excluir.\");\n        }\n        currentRows = currentRows.filter((r) => String(r.id) !== String(id));\n        renderRows(currentRows);\n      } catch (err) {\n        alert(err.message || \"Erro ao excluir.\");\n        btn.disabled = false;\n        btn.textContent = \"Excluir\";\n      }\n    }\n\n    function toCsv(rows) {\n      const headers = [\n        \"criado_em\", \"nome\", \"email\", \"whatsapp\", \"cidade\", \"creci\", \"experiencia\",\n        \"captacao\", \"regioes\", \"tipos_imovel\", \"disponibilidade\", \"veiculo\",\n        \"portfolio\", \"remuneracao\", \"sobre_voce\", \"lgpd\", \"extra_respostas\",\n      ];\n      const escCsv = (v) => `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n      const lines = [headers.join(\",\")];\n      rows.forEach((r) => lines.push(headers.map((h) => escCsv(r[h])).join(\",\")));\n      return lines.join(\"\\r\\n\");\n    }\n\n    // ---------------------------------------------------------------\n    // Páginas (visão geral)\n    // ---------------------------------------------------------------\n\n    /** Redesenha a lista de páginas a partir de extraPagesDraft (fonte única de verdade). */\n    function renderPagesOverview() {\n      const fixedBefore = [\n        { name: \"Tela inicial\", tag: \"abertura\" },\n        ...BUILTIN_STEPS.map((name) => ({ name, tag: \"fixa\" })),\n      ];\n      const extras = extraPagesDraft.map((p, i) => ({\n        name: `${String(6 + i).padStart(2, \"0\")} · ${p.title || \"Página extra\"}`,\n        tag: \"extra\",\n        extraIndex: i,\n      }));\n      const fixedAfter = [{ name: \"Agradecimento\", tag: \"final\" }];\n      const all = [...fixedBefore, ...extras, ...fixedAfter];\n\n      document.getElementById(\"pages-overview\").innerHTML = all\n        .map((it, i) => {\n          const draggable = it.extraIndex !== undefined;\n          return `<li class=\"${draggable ? \"\" : \"is-fixed\"}\" ${draggable ? `data-extra-index=\"${it.extraIndex}\"` : \"\"}>\n            <span class=\"drag-handle ${draggable ? \"\" : \"drag-handle--disabled\"}\" title=\"${draggable ? \"Arraste pra reordenar\" : \"Página fixa\"}\">⠿</span>\n            <span class=\"page-badge\">${i + 1}</span>\n            <span class=\"page-name\">${esc(it.name)}</span>\n            <span class=\"page-tag\">${esc(it.tag)}</span>\n          </li>`;\n        })\n        .join(\"\");\n    }\n\n    /** Arrastar (mouse/toque) pra reordenar as páginas extras na lista de visão geral. */\n    function initPagesDrag() {\n      const listEl = document.getElementById(\"pages-overview\");\n      let draggedRef = null;\n\n      listEl.addEventListener(\"pointerdown\", (e) => {\n        const handle = e.target.closest(\".drag-handle:not(.drag-handle--disabled)\");\n        if (!handle) return;\n        const li = handle.closest(\"li[data-extra-index]\");\n        if (!li) return;\n\n        draggedRef = extraPagesDraft[Number(li.dataset.extraIndex)];\n        li.classList.add(\"is-dragging\");\n        e.preventDefault();\n\n        const onMove = (ev) => {\n          if (!draggedRef) return;\n          const items = Array.from(listEl.querySelectorAll(\"li[data-extra-index]\"));\n          const hovered = items.find((item) => {\n            const r = item.getBoundingClientRect();\n            return ev.clientY >= r.top && ev.clientY <= r.bottom;\n          });\n          if (!hovered) return;\n\n          const targetIdx = Number(hovered.dataset.extraIndex);\n          const currentIdx = extraPagesDraft.indexOf(draggedRef);\n          if (targetIdx !== currentIdx) {\n            extraPagesDraft.splice(currentIdx, 1);\n            extraPagesDraft.splice(targetIdx, 0, draggedRef);\n            renderPagesOverview();\n            const newIdx = extraPagesDraft.indexOf(draggedRef);\n            const newLi = listEl.querySelector(`li[data-extra-index=\"${newIdx}\"]`);\n            if (newLi) newLi.classList.add(\"is-dragging\");\n          }\n        };\n\n        const onUp = () => {\n          window.removeEventListener(\"pointermove\", onMove);\n          window.removeEventListener(\"pointerup\", onUp);\n          listEl.querySelectorAll(\".is-dragging\").forEach((el) => el.classList.remove(\"is-dragging\"));\n          draggedRef = null;\n          renderExtraPagesEditor(); // mantém a aba Configurações sincronizada\n        };\n\n        window.addEventListener(\"pointermove\", onMove);\n        window.addEventListener(\"pointerup\", onUp);\n      });\n    }\n\n    // ---------------------------------------------------------------\n    // Configurações — páginas extras (multi-página, reordenável)\n    // ---------------------------------------------------------------\n\n    const QUESTION_TYPES_WITH_OPTIONS = [\"escolha\", \"checkbox\"];\n\n    function questionRowHtml(pi, qi, q, isFirst, isLast) {\n      return `\n        <div class=\"extra-q\" data-page-index=\"${pi}\" data-q-index=\"${qi}\">\n          <div class=\"extra-q__row\">\n            <div class=\"extra-q__move\">\n              <button type=\"button\" class=\"btn-icon q-move-up\" ${isFirst ? \"disabled\" : \"\"} title=\"Mover pra cima\">↑</button>\n              <button type=\"button\" class=\"btn-icon q-move-down\" ${isLast ? \"disabled\" : \"\"} title=\"Mover pra baixo\">↓</button>\n            </div>\n            <input type=\"text\" class=\"extra-q-label\" placeholder=\"Pergunta\" value=\"${esc(q.label)}\" />\n            <select class=\"extra-q-type settings-select\">\n              <option value=\"texto\" ${q.type === \"texto\" ? \"selected\" : \"\"}>Texto curto (escrever)</option>\n              <option value=\"textarea\" ${q.type === \"textarea\" ? \"selected\" : \"\"}>Texto longo (escrever)</option>\n              <option value=\"escolha\" ${q.type === \"escolha\" ? \"selected\" : \"\"}>Múltipla escolha — uma opção (botão)</option>\n              <option value=\"checkbox\" ${q.type === \"checkbox\" ? \"selected\" : \"\"}>Múltipla escolha — várias opções (botão)</option>\n              <option value=\"simnao\" ${q.type === \"simnao\" ? \"selected\" : \"\"}>Sim ou não (botão)</option>\n            </select>\n            <label class=\"extra-q__required\">\n              <input type=\"checkbox\" class=\"extra-q-required\" ${q.required ? \"checked\" : \"\"} /> Obrigatória\n            </label>\n            <button type=\"button\" class=\"btn-delete extra-q-remove\">Remover</button>\n          </div>\n          <textarea\n            class=\"extra-q-options\"\n            placeholder=\"Uma opção por linha\"\n            style=\"${QUESTION_TYPES_WITH_OPTIONS.includes(q.type) ? \"\" : \"display:none;\"}\"\n          >${esc((q.options || []).join(\"\\n\"))}</textarea>\n        </div>`;\n    }\n\n    function pageHtml(pi, page, isFirst, isLast) {\n      const questions = page.questions || [];\n      return `\n        <div class=\"extra-page\" data-page-index=\"${pi}\">\n          <div class=\"extra-page__header\">\n            <div class=\"extra-page__move\">\n              <button type=\"button\" class=\"btn-icon page-move-up\" ${isFirst ? \"disabled\" : \"\"} title=\"Mover página pra cima\">↑</button>\n              <button type=\"button\" class=\"btn-icon page-move-down\" ${isLast ? \"disabled\" : \"\"} title=\"Mover página pra baixo\">↓</button>\n            </div>\n            <input type=\"text\" class=\"extra-page-title\" placeholder=\"Título da página\" value=\"${esc(page.title)}\" />\n            <button type=\"button\" class=\"btn-delete page-remove\">Remover página</button>\n          </div>\n          <div class=\"extra-page__questions\">\n            ${\n              questions.length\n                ? questions.map((q, qi) => questionRowHtml(pi, qi, q, qi === 0, qi === questions.length - 1)).join(\"\")\n                : '<p class=\"field__hint\">Nenhuma pergunta nessa página ainda.</p>'\n            }\n          </div>\n          <button type=\"button\" class=\"btn-add-question\" data-add-question-to=\"${pi}\">+ Adicionar pergunta nesta página</button>\n        </div>`;\n    }\n\n    function renderExtraPagesEditor() {\n      const container = document.getElementById(\"extra-pages-editor\");\n      if (!extraPagesDraft.length) {\n        container.innerHTML = '<p class=\"field__hint\">Nenhuma página extra ainda.</p>';\n        return;\n      }\n      container.innerHTML = extraPagesDraft\n        .map((page, pi) => pageHtml(pi, page, pi === 0, pi === extraPagesDraft.length - 1))\n        .join(\"\");\n    }\n\n    /** Lê os campos atualmente na tela e grava de volta em extraPagesDraft. */\n    function syncExtraPagesFromDom() {\n      document.querySelectorAll(\".extra-page\").forEach((pageEl) => {\n        const pi = Number(pageEl.dataset.pageIndex);\n        const page = extraPagesDraft[pi];\n        if (!page) return;\n        page.title = pageEl.querySelector(\".extra-page-title\").value;\n\n        pageEl.querySelectorAll(\".extra-q\").forEach((qEl) => {\n          const qi = Number(qEl.dataset.qIndex);\n          const q = page.questions[qi];\n          if (!q) return;\n          q.label = qEl.querySelector(\".extra-q-label\").value;\n          q.type = qEl.querySelector(\".extra-q-type\").value;\n          q.required = qEl.querySelector(\".extra-q-required\").checked;\n          q.options = qEl\n            .querySelector(\".extra-q-options\")\n            .value.split(\"\\n\")\n            .map((s) => s.trim())\n            .filter(Boolean);\n        });\n      });\n    }\n\n    function addPage() {\n      syncExtraPagesFromDom();\n      extraPagesDraft.push({ title: `Página extra ${extraPagesDraft.length + 1}`, questions: [] });\n      renderExtraPagesEditor();\n      renderPagesOverview();\n    }\n\n    function swapItems(arr, i, j) {\n      const tmp = arr[i];\n      arr[i] = arr[j];\n      arr[j] = tmp;\n    }\n\n    /** Preenche buracos de uma config salva antes desta versão. */\n    function fillConfigDefaults(saved) {\n      const s = saved || {};\n      let extraPages = [];\n      if (Array.isArray(s.extraPages)) {\n        extraPages = s.extraPages;\n      } else if (Array.isArray(s.extraQuestions) && s.extraQuestions.length) {\n        extraPages = [{ title: \"Perguntas extras\", questions: s.extraQuestions }];\n      }\n      return {\n        capa: { ...DEFAULT_CONFIG.capa, ...(s.capa || {}) },\n        logo: { ...DEFAULT_CONFIG.logo, ...(s.logo || {}) },\n        landing: { ...DEFAULT_CONFIG.landing, ...(s.landing || {}) },\n        thanks: { ...DEFAULT_CONFIG.thanks, ...(s.thanks || {}) },\n        extraPages,\n      };\n    }\n\n    function applyConfigToForm(cfg) {\n      setImagePreview(document.getElementById(\"cfg-capa-preview\"), cfg.capa.image || \"\");\n      document.getElementById(\"cfg-capa-status\").textContent = \"\";\n      document.getElementById(\"cfg-capa-position\").value = cfg.capa.position || \"center\";\n      document.getElementById(\"cfg-capa-gradient\").checked = cfg.capa.gradient !== false;\n      setImagePreview(document.getElementById(\"cfg-logo-preview\"), cfg.logo.image || \"\");\n      document.getElementById(\"cfg-logo-status\").textContent = \"\";\n      document.getElementById(\"cfg-logo-position\").value = cfg.logo.position || \"top-left\";\n      document.getElementById(\"cfg-logo-size\").value = cfg.logo.size || \"medio\";\n      document.getElementById(\"cfg-landing-title\").value = cfg.landing.title || \"\";\n      document.getElementById(\"cfg-landing-title-size\").value = cfg.landing.titleSize || \"normal\";\n      document.getElementById(\"cfg-landing-subtitle\").value = cfg.landing.subtitle || \"\";\n      document.getElementById(\"cfg-landing-button\").value = cfg.landing.buttonLabel || \"\";\n      document.getElementById(\"cfg-landing-align\").value = cfg.landing.textAlign || \"left\";\n      document.getElementById(\"cfg-landing-pos\").value = cfg.landing.textPosition || \"bottom\";\n      document.getElementById(\"cfg-thanks-title\").value = cfg.thanks.title || \"\";\n      document.getElementById(\"cfg-thanks-message\").value = cfg.thanks.message || \"\";\n      document.getElementById(\"cfg-thanks-align\").value = cfg.thanks.textAlign || \"center\";\n      document.getElementById(\"cfg-thanks-pos\").value = cfg.thanks.textPosition || \"center\";\n      document.getElementById(\"cfg-thanks-whats-number\").value = cfg.thanks.whatsappNumber || \"\";\n      document.getElementById(\"cfg-thanks-whats-message\").value = cfg.thanks.whatsappMessage || \"\";\n      extraPagesDraft = (cfg.extraPages || []).map((p) => ({\n        title: p.title || \"\",\n        questions: (p.questions || []).map((q) => ({ ...q })),\n      }));\n      renderExtraPagesEditor();\n      renderPagesOverview();\n    }\n\n    async function loadConfigIntoForm() {\n      try {\n        const res = await fetch(\"/api/config\", { cache: \"no-store\" });\n        const data = await res.json();\n        applyConfigToForm(fillConfigDefaults(data.config));\n      } catch {\n        applyConfigToForm(DEFAULT_CONFIG);\n      }\n    }\n\n    function collectConfigFromForm() {\n      syncExtraPagesFromDom();\n\n      return {\n        capa: {\n          image: document.getElementById(\"cfg-capa-preview\").getAttribute(\"src\") || \"\",\n          position: document.getElementById(\"cfg-capa-position\").value,\n          gradient: document.getElementById(\"cfg-capa-gradient\").checked,\n        },\n        logo: {\n          image: document.getElementById(\"cfg-logo-preview\").getAttribute(\"src\") || \"\",\n          position: document.getElementById(\"cfg-logo-position\").value,\n          size: document.getElementById(\"cfg-logo-size\").value,\n        },\n        landing: {\n          title: document.getElementById(\"cfg-landing-title\").value.trim(),\n          titleSize: document.getElementById(\"cfg-landing-title-size\").value,\n          subtitle: document.getElementById(\"cfg-landing-subtitle\").value.trim(),\n          buttonLabel: document.getElementById(\"cfg-landing-button\").value.trim(),\n          textAlign: document.getElementById(\"cfg-landing-align\").value,\n          textPosition: document.getElementById(\"cfg-landing-pos\").value,\n        },\n        thanks: {\n          title: document.getElementById(\"cfg-thanks-title\").value.trim(),\n          message: document.getElementById(\"cfg-thanks-message\").value.trim(),\n          textAlign: document.getElementById(\"cfg-thanks-align\").value,\n          textPosition: document.getElementById(\"cfg-thanks-pos\").value,\n          whatsappNumber: document.getElementById(\"cfg-thanks-whats-number\").value.trim(),\n          whatsappMessage: document.getElementById(\"cfg-thanks-whats-message\").value.trim(),\n        },\n        extraPages: extraPagesDraft,\n      };\n    }\n\n    async function saveConfig(ids) {\n      const btn = document.getElementById((ids && ids.btn) || \"btn-save-config\");\n      const errorEl = document.getElementById((ids && ids.error) || \"config-error\");\n      const successEl = document.getElementById((ids && ids.success) || \"config-success\");\n      errorEl.classList.remove(\"is-visible\");\n      successEl.classList.remove(\"is-visible\");\n\n      const token = sessionStorage.getItem(STORAGE_KEY);\n      const payload = collectConfigFromForm();\n      const originalLabel = btn.textContent;\n\n      btn.disabled = true;\n      btn.textContent = \"Salvando…\";\n\n      try {\n        const res = await fetch(\"/admin/config\", {\n          method: \"POST\",\n          headers: { \"content-type\": \"application/json\", \"x-admin-token\": token },\n          body: JSON.stringify(payload),\n        });\n        const data = await res.json().catch(() => ({}));\n        if (!res.ok || !data.ok) {\n          throw new Error(data.error || \"Não foi possível salvar.\");\n        }\n        applyConfigToForm(data.config);\n        successEl.classList.add(\"is-visible\");\n        refreshPreview();\n      } catch (err) {\n        errorEl.textContent = err.message || \"Erro ao salvar.\";\n        errorEl.classList.add(\"is-visible\");\n      } finally {\n        btn.disabled = false;\n        btn.textContent = originalLabel;\n      }\n    }\n\n    // ---------------------------------------------------------------\n    // Visualizar\n    // ---------------------------------------------------------------\n\n    function refreshPreview() {\n      const frame = document.getElementById(\"preview-frame\");\n      frame.src = \"/?admin-preview=\" + Date.now();\n    }\n\n    // ---------------------------------------------------------------\n    // Login / navegação\n    // ---------------------------------------------------------------\n\n    async function tryEnter(token) {\n      const errorEl = document.getElementById(\"gate-error\");\n      errorEl.classList.remove(\"is-visible\");\n      try {\n        const rows = await loadData(token);\n        sessionStorage.setItem(STORAGE_KEY, token);\n        document.getElementById(\"gate\").classList.add(\"hidden\");\n        document.getElementById(\"content\").classList.remove(\"hidden\");\n        renderRows(rows);\n        loadConfigIntoForm();\n        refreshPreview();\n      } catch (err) {\n        errorEl.textContent = err.message;\n        errorEl.classList.add(\"is-visible\");\n      }\n    }\n\n    document.getElementById(\"btn-enter\").addEventListener(\"click\", () => {\n      const token = document.getElementById(\"token-input\").value.trim();\n      if (token) tryEnter(token);\n    });\n\n    document.getElementById(\"token-input\").addEventListener(\"keydown\", (e) => {\n      if (e.key === \"Enter\") document.getElementById(\"btn-enter\").click();\n    });\n\n    document.getElementById(\"btn-refresh\").addEventListener(\"click\", async () => {\n      const token = sessionStorage.getItem(STORAGE_KEY);\n      if (token) renderRows(await loadData(token));\n    });\n\n    document.getElementById(\"rows\").addEventListener(\"click\", (e) => {\n      const btn = e.target.closest(\"[data-delete-id]\");\n      if (btn) deleteRow(btn.dataset.deleteId, btn);\n    });\n\n    document.getElementById(\"btn-csv\").addEventListener(\"click\", () => {\n      const blob = new Blob([toCsv(currentRows)], { type: \"text/csv;charset=utf-8;\" });\n      const link = document.createElement(\"a\");\n      link.href = URL.createObjectURL(blob);\n      link.download = \"candidaturas-solua.csv\";\n      link.click();\n    });\n\n    document.querySelectorAll(\".tab-btn\").forEach((btn) => {\n      btn.addEventListener(\"click\", () => {\n        document.querySelectorAll(\".tab-btn\").forEach((b) => b.classList.toggle(\"is-active\", b === btn));\n        document.querySelectorAll(\".tab-panel\").forEach((p) => {\n          p.classList.toggle(\"is-active\", p.id === \"tab-\" + btn.dataset.tab);\n        });\n        if (btn.dataset.tab === \"preview\") refreshPreview();\n      });\n    });\n\n    document.getElementById(\"btn-preview-refresh\").addEventListener(\"click\", refreshPreview);\n\n    document.getElementById(\"btn-preview-skip\").addEventListener(\"click\", () => {\n      document.getElementById(\"preview-frame\").src = \"/?preview_skip=1&t=\" + Date.now();\n    });\n\n    document.getElementById(\"btn-add-page\").addEventListener(\"click\", addPage);\n\n    document.getElementById(\"btn-save-config\").addEventListener(\"click\", () => saveConfig());\n\n    document.getElementById(\"btn-save-pages-order\").addEventListener(\"click\", () =>\n      saveConfig({ btn: \"btn-save-pages-order\", error: \"pages-error\", success: \"pages-success\" })\n    );\n\n    // ---------------------------------------------------------------\n    // Upload de imagens (capa e logo)\n    // ---------------------------------------------------------------\n\n    function setImagePreview(imgEl, value) {\n      if (value) {\n        imgEl.src = value;\n        imgEl.classList.remove(\"is-empty\");\n      } else {\n        imgEl.removeAttribute(\"src\");\n        imgEl.classList.add(\"is-empty\");\n      }\n    }\n\n    function resizeImageFile(file, { maxDim, mime, quality }) {\n      return new Promise((resolve, reject) => {\n        if (!file.type || !file.type.startsWith(\"image/\")) {\n          reject(new Error(\"Escolha um arquivo de imagem.\"));\n          return;\n        }\n        const reader = new FileReader();\n        reader.onerror = () => reject(new Error(\"Não foi possível ler o arquivo.\"));\n        reader.onload = () => {\n          const img = new Image();\n          img.onerror = () => reject(new Error(\"Arquivo de imagem inválido.\"));\n          img.onload = () => {\n            let { width, height } = img;\n            if (width > maxDim || height > maxDim) {\n              if (width >= height) {\n                height = Math.round((height * maxDim) / width);\n                width = maxDim;\n              } else {\n                width = Math.round((width * maxDim) / height);\n                height = maxDim;\n              }\n            }\n            const canvas = document.createElement(\"canvas\");\n            canvas.width = width;\n            canvas.height = height;\n            canvas.getContext(\"2d\").drawImage(img, 0, 0, width, height);\n            resolve(canvas.toDataURL(mime, quality));\n          };\n          img.src = reader.result;\n        };\n        reader.readAsDataURL(file);\n      });\n    }\n\n    async function handleImageUpload(file, opts, previewEl, statusEl) {\n      statusEl.textContent = \"Processando imagem…\";\n      statusEl.classList.remove(\"is-error\");\n      try {\n        const mime = file.type === \"image/png\" || file.type === \"image/webp\" ? \"image/png\" : \"image/jpeg\";\n        const dataUrl = await resizeImageFile(file, { maxDim: opts.maxDim, mime, quality: opts.quality });\n        if (dataUrl.length > opts.maxChars) {\n          throw new Error(\n            `Imagem ainda ficou grande (${Math.round(dataUrl.length / 1024)} KB) mesmo compactada. ` +\n              \"Tente uma imagem mais simples ou já reduzida.\"\n          );\n        }\n        setImagePreview(previewEl, dataUrl);\n        statusEl.textContent = `Pronto (${Math.round(dataUrl.length / 1024)} KB).`;\n      } catch (err) {\n        statusEl.textContent = err.message || \"Erro ao processar a imagem.\";\n        statusEl.classList.add(\"is-error\");\n      }\n    }\n\n    document.getElementById(\"cfg-capa-file\").addEventListener(\"change\", (e) => {\n      const file = e.target.files[0];\n      e.target.value = \"\";\n      if (!file) return;\n      handleImageUpload(\n        file,\n        { maxDim: 1600, maxChars: 900000, quality: 0.78 },\n        document.getElementById(\"cfg-capa-preview\"),\n        document.getElementById(\"cfg-capa-status\")\n      );\n    });\n\n    document.getElementById(\"cfg-logo-file\").addEventListener(\"change\", (e) => {\n      const file = e.target.files[0];\n      e.target.value = \"\";\n      if (!file) return;\n      handleImageUpload(\n        file,\n        { maxDim: 400, maxChars: 350000, quality: 0.9 },\n        document.getElementById(\"cfg-logo-preview\"),\n        document.getElementById(\"cfg-logo-status\")\n      );\n    });\n\n    document.getElementById(\"cfg-capa-remove\").addEventListener(\"click\", () => {\n      setImagePreview(document.getElementById(\"cfg-capa-preview\"), \"\");\n      document.getElementById(\"cfg-capa-status\").textContent = \"\";\n    });\n\n    document.getElementById(\"cfg-logo-remove\").addEventListener(\"click\", () => {\n      setImagePreview(document.getElementById(\"cfg-logo-preview\"), \"\");\n      document.getElementById(\"cfg-logo-status\").textContent = \"\";\n    });\n\n    initPagesDrag();\n\n    document.getElementById(\"extra-pages-editor\").addEventListener(\"click\", (e) => {\n      const addQBtn = e.target.closest(\"[data-add-question-to]\");\n      if (addQBtn) {\n        syncExtraPagesFromDom();\n        const pi = Number(addQBtn.dataset.addQuestionTo);\n        extraPagesDraft[pi].questions.push({ label: \"\", type: \"texto\", options: [], required: false });\n        renderExtraPagesEditor();\n        return;\n      }\n\n      const pageRemoveBtn = e.target.closest(\".page-remove\");\n      if (pageRemoveBtn) {\n        syncExtraPagesFromDom();\n        const pi = Number(pageRemoveBtn.closest(\".extra-page\").dataset.pageIndex);\n        extraPagesDraft.splice(pi, 1);\n        renderExtraPagesEditor();\n        renderPagesOverview();\n        return;\n      }\n\n      const pageUpBtn = e.target.closest(\".page-move-up\");\n      if (pageUpBtn) {\n        syncExtraPagesFromDom();\n        const pi = Number(pageUpBtn.closest(\".extra-page\").dataset.pageIndex);\n        if (pi > 0) swapItems(extraPagesDraft, pi, pi - 1);\n        renderExtraPagesEditor();\n        renderPagesOverview();\n        return;\n      }\n\n      const pageDownBtn = e.target.closest(\".page-move-down\");\n      if (pageDownBtn) {\n        syncExtraPagesFromDom();\n        const pi = Number(pageDownBtn.closest(\".extra-page\").dataset.pageIndex);\n        if (pi < extraPagesDraft.length - 1) swapItems(extraPagesDraft, pi, pi + 1);\n        renderExtraPagesEditor();\n        renderPagesOverview();\n        return;\n      }\n\n      const qRemoveBtn = e.target.closest(\".extra-q-remove\");\n      if (qRemoveBtn) {\n        syncExtraPagesFromDom();\n        const qEl = qRemoveBtn.closest(\".extra-q\");\n        const pi = Number(qEl.dataset.pageIndex);\n        const qi = Number(qEl.dataset.qIndex);\n        extraPagesDraft[pi].questions.splice(qi, 1);\n        renderExtraPagesEditor();\n        return;\n      }\n\n      const qUpBtn = e.target.closest(\".q-move-up\");\n      if (qUpBtn) {\n        syncExtraPagesFromDom();\n        const qEl = qUpBtn.closest(\".extra-q\");\n        const pi = Number(qEl.dataset.pageIndex);\n        const qi = Number(qEl.dataset.qIndex);\n        if (qi > 0) swapItems(extraPagesDraft[pi].questions, qi, qi - 1);\n        renderExtraPagesEditor();\n        return;\n      }\n\n      const qDownBtn = e.target.closest(\".q-move-down\");\n      if (qDownBtn) {\n        syncExtraPagesFromDom();\n        const qEl = qDownBtn.closest(\".extra-q\");\n        const pi = Number(qEl.dataset.pageIndex);\n        const qi = Number(qEl.dataset.qIndex);\n        const questions = extraPagesDraft[pi].questions;\n        if (qi < questions.length - 1) swapItems(questions, qi, qi + 1);\n        renderExtraPagesEditor();\n      }\n    });\n\n    document.getElementById(\"extra-pages-editor\").addEventListener(\"change\", (e) => {\n      if (e.target.classList.contains(\"extra-q-type\")) {\n        const optionsEl = e.target.closest(\".extra-q\").querySelector(\".extra-q-options\");\n        optionsEl.style.display = QUESTION_TYPES_WITH_OPTIONS.includes(e.target.value) ? \"\" : \"none\";\n      }\n    });\n\n    // reflete o título da página na aba Páginas em tempo real, sem perder o foco do campo\n    document.getElementById(\"extra-pages-editor\").addEventListener(\"input\", (e) => {\n      if (!e.target.classList.contains(\"extra-page-title\")) return;\n      const pi = Number(e.target.closest(\".extra-page\").dataset.pageIndex);\n      if (extraPagesDraft[pi]) {\n        extraPagesDraft[pi].title = e.target.value;\n        renderPagesOverview();\n      }\n    });\n\n    // reentra sozinho se já tiver token salvo nesta aba\n    const savedToken = sessionStorage.getItem(STORAGE_KEY);\n    if (savedToken) tryEnter(savedToken);\n  </script>\n</body>\n</html>\n";

const REQUIRED_FIELDS = [
  "nome", "email", "whatsapp", "cidade", "experiencia", "captacao",
  "regioes", "disponibilidade", "remuneracao", "lgpd",
];

function isNonEmptyString(value) {
  return typeof value === "string" && value.trim().length > 0;
}

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
  });
}

async function handleSubmit(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ ok: false, error: "JSON inválido." }, 400);
  }

  for (const field of REQUIRED_FIELDS) {
    if (!isNonEmptyString(body[field])) {
      return jsonResponse({ ok: false, error: `Campo obrigatório ausente: ${field}` }, 400);
    }
  }

  if (!Array.isArray(body.tiposImovel) || body.tiposImovel.length === 0) {
    return jsonResponse({ ok: false, error: "Selecione ao menos um tipo de imóvel." }, 400);
  }

  const lgpd = body.lgpd.trim().toLowerCase();
  if (lgpd !== "sim") {
    return jsonResponse(
      { ok: false, error: "É necessário autorizar o tratamento dos dados (LGPD) para enviar a candidatura." },
      400
    );
  }

  if (isNonEmptyString(body.website)) {
    return jsonResponse({ ok: true }); // honeypot: finge sucesso, não grava
  }

  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim());
  if (!emailOk) {
    return jsonResponse({ ok: false, error: "E-mail inválido." }, 400);
  }

  const now = new Date().toISOString();
  const extraRespostas = body.extraRespostas && typeof body.extraRespostas === "object" ? body.extraRespostas : {};

  if (!env.DB) {
    return jsonResponse(
      { ok: false, error: "Banco de dados não configurado neste Worker (falta o binding DB)." },
      500
    );
  }

  try {
    await env.DB.prepare(
      `INSERT INTO candidaturas
        (nome, email, whatsapp, cidade, creci, experiencia, captacao, regioes,
         tipos_imovel, disponibilidade, veiculo, portfolio, remuneracao, sobre_voce, lgpd, criado_em, extra_respostas)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    )
      .bind(
        body.nome.trim(),
        body.email.trim(),
        body.whatsapp.trim(),
        body.cidade.trim(),
        (body.creci || "").trim() || null,
        body.experiencia.trim(),
        body.captacao.trim(),
        body.regioes.trim(),
        body.tiposImovel.join(", "),
        body.disponibilidade.trim(),
        (body.veiculo || "").trim() || null,
        (body.portfolio || "").trim() || null,
        body.remuneracao.trim(),
        (body.sobreVoce || "").trim() || null,
        "Sim",
        now,
        Object.keys(extraRespostas).length ? JSON.stringify(extraRespostas) : null
      )
      .run();
  } catch (err) {
    return jsonResponse({ ok: false, error: "Erro ao salvar candidatura." }, 500);
  }

  return jsonResponse({ ok: true });
}

function isAuthorizedAdmin(request, env) {
  const token = request.headers.get("x-admin-token") || "";
  return Boolean(env.ADMIN_TOKEN) && token === env.ADMIN_TOKEN;
}

async function handleAdminData(request, env) {
  if (!isAuthorizedAdmin(request, env)) {
    return jsonResponse({ ok: false, error: "Não autorizado." }, 401);
  }

  if (!env.DB) {
    return jsonResponse({ ok: false, error: "Banco de dados não configurado (falta o binding DB)." }, 500);
  }

  const { results } = await env.DB.prepare(
    "SELECT * FROM candidaturas ORDER BY criado_em DESC"
  ).all();

  return jsonResponse({ ok: true, rows: results });
}

/** Exclui uma candidatura pelo id (protegida por token). */
async function handleAdminDelete(request, env, id) {
  if (!isAuthorizedAdmin(request, env)) {
    return jsonResponse({ ok: false, error: "Não autorizado." }, 401);
  }

  if (!env.DB) {
    return jsonResponse({ ok: false, error: "Banco de dados não configurado (falta o binding DB)." }, 500);
  }

  if (!id || !/^\d+$/.test(id)) {
    return jsonResponse({ ok: false, error: "ID inválido." }, 400);
  }

  await env.DB.prepare("DELETE FROM candidaturas WHERE id = ?").bind(id).run();

  return jsonResponse({ ok: true });
}

function str(value, max) {
  return typeof value === "string" ? value.trim().slice(0, max) : "";
}

const QUESTION_TYPES = ["texto", "textarea", "escolha", "checkbox", "simnao"];
const QUESTION_TYPES_WITH_OPTIONS = ["escolha", "checkbox"];
const LOGO_POSITIONS = ["top-left", "top-center", "top-right", "center", "bottom-left", "bottom-right"];
const LOGO_SIZES = ["pequeno", "medio", "grande"];
const TEXT_ALIGNS = ["left", "center", "right"];
const TEXT_POSITIONS = ["top", "center", "bottom"];

function sanitizeQuestions(rawQuestions, pagePrefix) {
  return (Array.isArray(rawQuestions) ? rawQuestions : [])
    .slice(0, 20)
    .map((q, i) => ({
      id: `${pagePrefix}q${i + 1}`,
      label: str(q && q.label, 200),
      type: QUESTION_TYPES.includes(q && q.type) ? q.type : "texto",
      options:
        q && QUESTION_TYPES_WITH_OPTIONS.includes(q.type) && Array.isArray(q.options)
          ? q.options.map((o) => str(o, 100)).filter(Boolean).slice(0, 10)
          : [],
      required: Boolean(q && q.required),
    }))
    .filter((q) => q.label);
}

function sanitizePages(rawPages) {
  return (Array.isArray(rawPages) ? rawPages : [])
    .slice(0, 10)
    .map((p, i) => ({
      id: "p" + (i + 1),
      title: str(p && p.title, 100) || `Página extra ${i + 1}`,
      questions: sanitizeQuestions(p && p.questions, `p${i + 1}_`),
    }))
    .filter((p) => p.questions.length > 0);
}

/** Valida e normaliza a configuração recebida do painel admin antes de salvar. */
function sanitizeConfig(input) {
  const landing = input && input.landing ? input.landing : {};
  const thanks = input && input.thanks ? input.thanks : {};
  const capa = input && input.capa ? input.capa : {};
  const logo = input && input.logo ? input.logo : {};

  return {
    capa: {
      image: str(capa.image, 2000000), // aceita arquivo enviado (data URI), não só link
      position: ["top", "center", "bottom"].includes(capa.position) ? capa.position : "center",
      gradient: capa.gradient !== false,
    },
    logo: {
      image: str(logo.image, 2000000), // aceita arquivo enviado (data URI), não só link
      position: LOGO_POSITIONS.includes(logo.position) ? logo.position : "top-left",
      size: LOGO_SIZES.includes(logo.size) ? logo.size : "medio",
    },
    landing: {
      title: str(landing.title, 200),
      titleSize: ["small", "normal", "large"].includes(landing.titleSize) ? landing.titleSize : "normal",
      subtitle: str(landing.subtitle, 600),
      buttonLabel: str(landing.buttonLabel, 60),
      textAlign: TEXT_ALIGNS.includes(landing.textAlign) ? landing.textAlign : "left",
      textPosition: TEXT_POSITIONS.includes(landing.textPosition) ? landing.textPosition : "bottom",
    },
    thanks: {
      title: str(thanks.title, 200),
      message: str(thanks.message, 600),
      textAlign: TEXT_ALIGNS.includes(thanks.textAlign) ? thanks.textAlign : "center",
      textPosition: TEXT_POSITIONS.includes(thanks.textPosition) ? thanks.textPosition : "center",
      whatsappNumber: str(thanks.whatsappNumber, 30),
      whatsappMessage: str(thanks.whatsappMessage, 400),
    },
    extraPages: sanitizePages(input && input.extraPages),
  };
}

/** Retorna a configuração salva (ou null se ninguém salvou nada ainda). */
async function handleGetConfig(env) {
  if (!env.DB) return jsonResponse({ ok: true, config: null });
  try {
    const row = await env.DB.prepare("SELECT data FROM site_config WHERE id = 1").first();
    return jsonResponse({ ok: true, config: row ? JSON.parse(row.data) : null });
  } catch {
    return jsonResponse({ ok: true, config: null });
  }
}

/** Salva a configuração (protegido por token). */
async function handleSaveConfig(request, env) {
  if (!isAuthorizedAdmin(request, env)) {
    return jsonResponse({ ok: false, error: "Não autorizado." }, 401);
  }

  if (!env.DB) {
    return jsonResponse({ ok: false, error: "Banco de dados não configurado (falta o binding DB)." }, 500);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ ok: false, error: "JSON inválido." }, 400);
  }

  const config = sanitizeConfig(body);

  await env.DB.prepare(
    "INSERT INTO site_config (id, data) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET data = excluded.data"
  )
    .bind(JSON.stringify(config))
    .run();

  return jsonResponse({ ok: true, config });
}

export default {
  async fetch(request, env) {
    try {
      const url = new URL(request.url);

      if (url.pathname === "/api/submit") {
        if (request.method !== "POST") return jsonResponse({ ok: false, error: "Método não permitido." }, 405);
        return await handleSubmit(request, env);
      }

      if (url.pathname === "/api/config") {
        return await handleGetConfig(env);
      }

      if (url.pathname === "/admin/config" && request.method === "POST") {
        return await handleSaveConfig(request, env);
      }

      if (url.pathname.startsWith("/admin/data/") && request.method === "DELETE") {
        const id = url.pathname.slice("/admin/data/".length);
        return await handleAdminDelete(request, env, id);
      }

      if (url.pathname === "/admin/data") {
        return await handleAdminData(request, env);
      }

      if (url.pathname === "/admin") {
        return new Response(ADMIN_HTML, {
          headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" },
        });
      }

      if (url.pathname === "/styles.css") {
        return new Response(STYLES_CSS, {
          headers: { "content-type": "text/css; charset=utf-8", "cache-control": "no-store" },
        });
      }

      if (url.pathname === "/app.js") {
        return new Response(APP_JS, {
          headers: { "content-type": "text/javascript; charset=utf-8", "cache-control": "no-store" },
        });
      }

      if (url.pathname === "/images/placeholder.svg") {
        return new Response(PLACEHOLDER_SVG, {
          headers: { "content-type": "image/svg+xml; charset=utf-8", "cache-control": "no-store" },
        });
      }

      return new Response(INDEX_HTML, {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" },
      });
    } catch (err) {
      // Nunca deixa a página de erro genérica da Cloudflare aparecer sem explicação:
      // mostra a mensagem real pra dar pra diagnosticar na hora.
      const message = (err && err.stack) || String(err);
      return new Response("Erro no Worker:\n\n" + message, {
        status: 500,
        headers: { "content-type": "text/plain; charset=utf-8" },
      });
    }
  },
};
